INSERT INTO titles (id, "order", name, freq, parentId, nodeType) VALUES (191, 15, 'جامع أدعية القرآن المجيد والسنة الصحيحة (الأدعية المطلقة)', 'd', 158, 'category');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (827, 92, 1, '﴿ رَّبِّ أَعُوذُ بِكَ مِنۡ هَمَزَٰتِ ٱلشَّيَٰطِينِ ٩٧ وَأَعُوذُ بِكَ رَبِّ أَن يَحۡضُرُونِ ﴾', 1, 'الورد الأول. [المؤمنون: ٩٧، ٩٨]. (ص381)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (824, 92, 2, 'أعوذ بالله السميع العليم من الشيطان الرجيم.', 1, 'الورد الأول. (ص382)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (826, 92, 3, 'QuranText[(1:1:7)]', 1, 'الورد الأول. [الفاتحة]. (ص382)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (830, 92, 4, '﴿ سَمِعۡنَا وَأَطَعۡنَاۖ غُفۡرَانَكَ رَبَّنَا وَإِلَيۡكَ ٱلۡمَصِيرُ ﴾', 1, 'الورد الأول. [البقرة: ٢٨٦]. (ص383)', '', '', '﴿ سمعۡنا وأطعۡناۖ غفۡرانك ربنا وإليۡك ٱلۡمصير ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (831, 92, 5, '﴿ رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴾', 1, 'الورد الأول. [البقرة: ٢٨٦]. (ص383)', '', '', '﴿ ربنا لا تؤاخذۡنا إن نسينا أوۡ أخۡطأۡناۚ ربنا ولا تحۡملۡ عليۡنا إصۡرا كما حملۡتهۥ على ٱلذين من قبۡلناۚ ربنا ولا تحملۡنا ما لا طاقة لنا بهۦۖ وٱعۡف عنا وٱغۡفرۡ لنا وٱرۡحمۡناۚ أنت موۡلىنا فٱنصرۡنا على ٱلۡقوۡم ٱلۡكفرين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1983, 92, 6, 'اللهم إني أسألك يا اللهُ الواحدُ الأحدُ الصمدُ، الذي لم يلد، ولم يُولَدْ، ولم يكن له كُفُوًا أحدٌ، أن تغفر لي ذُنُوبي، إنك أنت الغفورُ الرحيم.', 1, 'الورد الأول. (ص383)', '', '', 'اللهم إني أسألك يا الله الواحد الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفوا أحد أن تغفر لي ذنوبي إنك أنت الغفور الرحيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (835, 92, 7, 'اللهم أنت ربي، لا إله إلا أنت خلقتَني، وأنا عبدُكَ، وأنا على عهدِكَ ووعدِكَ ما استطعتُ، أعوذ بك من شَرِّ ما صنعتُ، أبوءُ لك بنعمتِكَ عَلَيَّ، وأبوءُ بذنبي فاغفر لي، فإنه لا يغفرُ الذنوبَ إلا أنت.', 1, 'الورد الأول. (ص383)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1984, 92, 8, 'اللهم اغفر لِحَيِّنا وَمَيِّتِنا، وشاهدِنا وغائبِنا، وصغيرِنا وكبيرِنا، وذَكَرِنَا وأُنثَانا، اللهم من أَحْيَيْتَهُ مِنَّا، فَأَحْيِهِ على الإسلام، ومن توفيتَهُ مِنَّا، فَتَوَفَّهُ على الإيمان.', 1, 'الورد الأول. (ص384)', '', '', 'اللهم اغفر لحينا وميتنا وشاهدنا وغائبنا وصغيرنا وكبيرنا وذكرنا وأنثانا اللهم من أحييته منا فأحيه على الإسلام ومن توفيته منا فتوفه على الإيمان', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (832, 92, 9, 'QuranText[(3:8:8)]', 1, 'الورد الأول. [آل عمران: ٨]. (ص384)', '', '', '388', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (652, 92, 10, 'اللهم لك أسلمتُ، وبك آمنتُ، وعليك تَوَكَّلْتُ، وإليك أَنَبْتُ، وَبِكَ خَاصَمْتُ، اللهم إني أعوذ بِعِزَّتِكَ –لا إله إلا أنت– أن تُضِلَّني، أنت الحيُّ الذي لا يموت، والجنُّ والإنسُ يموتون.', 1, 'الورد الأول. (ص384)', '', '', 'اللهم لك أسلمت وبك آمنت وعليك توكلت وإليك أنبت وبك خاصمت اللهم إني أعوذ بعزتك –لا إله إلا أنت– أن تضلني أنت الحي الذي لا يموت والجن والإنس يموتون', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (651, 92, 11, 'اللهم إنا نسألُكَ أن تُجَدِّدَ الإيمانَ في قلوبنا.', 1, 'الورد الأول. (ص384)', '', '', 'اللهم إنا نسألك أن تجدد الإيمان في قلوبنا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (716, 92, 12, 'اللهم مُصَرِّفَ القلوبِ، صَرِّفْ قلوبَنا على طاعتك.', 1, 'الورد الأول. (ص384)', '', '', 'اللهم مصرف القلوب صرف قلوبنا على طاعتك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1985, 92, 13, 'اللَّهُمَّ ﴿ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ أَنتَ وَلِيِّۦ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ تَوَفَّنِي مُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ ﴾', 1, 'الورد الأول. [يوسف: ١٠١]. (ص385)', '', '', 'اللهم ﴿ فاطر ٱلسموت وٱلۡأرۡض أنت وليۦ في ٱلدنۡيا وٱلۡأخرةۖ توفني مسۡلما وألۡحقۡني بٱلصلحين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1986, 92, 14, 'اللهم إني أسألُكَ الهُدَى والسَّدَادَ.', 1, 'الورد الأول. (ص385)', '', '', 'اللهم إني أسألك الهدى والسداد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1987, 92, 15, 'يا مُقَلِّبَ القُلُوبِ ثَبِّتْ قلوبَنا على دينِكَ.', 1, 'الورد الأول. (ص385)', '', '', 'يا مقلب القلوب ثبت قلوبنا على دينك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (612, 92, 16, 'اللهم احفظني بالإسلام قائمًا، واحفظني بالإسلام قاعدًا، واحفظني بالإسلام راقدًا، ولا تُشْمِتْ بي عدوًّا حاسدًا، اللهم إني أسألُكَ من كل خيرٍ خزائنُه بيدك، وأعوذ بك من كل شرٍّ خزائنُه بيدك.', 1, 'الورد الأول. (ص385)', '', '', 'اللهم احفظني بالإسلام قائما واحفظني بالإسلام قاعدا واحفظني بالإسلام راقدا ولا تشمت بي عدوا حاسدا اللهم إني أسألك من كل خير خزائنه بيدك وأعوذ بك من كل شر خزائنه بيدك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (635, 92, 17, 'يا وليَّ الإسلامِ وأهلِهِ، مَسِّكْني الإسلامَ حتى ألقاك عليه.', 1, 'الورد الأول. (ص385)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1988, 92, 18, 'اللهم حَبِّبْ إلينا الإيمانَ، وزَيِّنْهُ في قُلُوبِنَا، وَكَرِّهْ إلينا الكُفْرَ وَالْفُسُوقَ والعِصْيانَ، واجعلنا مِنَ الرَّاشِدين.', 1, 'الورد الأول. (ص386)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1989, 92, 19, 'اللهم إنَّك قُلْتَ: ﴿ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ ﴾ [غافر: ٦٠]، وإنَّك لا تُخلِفُ الميعادَ، وإنِّي أسألُك كما هديتَني للإسلامِ: أن لا تَنْزِعَهُ مِنِّي، حتَّى تتوفَّاني وأنا مُسلِمٌ.', 1, 'الورد الأول. [موقوفٌ عن ابن عمر رضي الله عنهما]. (ص386)', '', '', 'اللهم إنك قلت ﴿ ٱدۡعوني أسۡتجبۡ لكمۡۚ ﴾ غافر ٦٠ وإنك لا تخلف الميعاد وإني أسألك كما هديتني للإسلام أن لا تنزعه مني حتى تتوفاني وأنا مسلم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1990, 92, 20, 'اللهم ارزقني شهادةً في سبيلِكَ، واجعل موتي في بَلَدِ رسولِكَ.', 1, 'الورد الأول. [موقوفٌ عن عمر رضي الله عنه]. (ص386)', '', '', 'اللهم ارزقني شهادة في سبيلك واجعل موتي في بلد رسولك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1991, 92, 21, 'اللهم تَوَفَّني مَعَ الأبرارِ، ولا تُخَلِّفْني مع الأشرارِ، وأَلْحِقني بالأخيار.', 1, 'الورد الأول. [من دعاء عمر رضي الله عنه]. (ص386)', '', '', 'اللهم توفني مع الأبرار ولا تخلفني مع الأشرار وألحقني بالأخيار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1992, 92, 22, 'اللهمَّ صَلِّ على محمدٍ، وعلى آلِ مُحَمَّدٍ، كما صَلَّيْتَ على إبراهيمَ، وعلى آلِ إبراهيم، إنَّك حميدٌ مجيد، اللهم بارِكْ على محمدٍ، وعلى آلِ محمد، كما باركتَ على إبراهيمَ، وعلى آلِ إبراهيمَ، إنَّك حميدٌ مجيد.', 1, 'الورد الأول. (ص386–387)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (647, 82, 1, '﴿ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةٗ وَهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدٗا ﴾', 1, 'الورد الثاني. [الكهف: ١٠]. (ص388)', '', '', '﴿ ربنا ءاتنا من لدنك رحۡمة وهيئۡ لنا منۡ أمۡرنا رشدا ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (686, 82, 2, '﴿ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَدۡخِلۡنِي بِرَحۡمَتِكَ فِي عِبَادِكَ ٱلصَّٰلِحِينَ ﴾', 1, 'الورد الثاني. [النمل: ١٩]. (ص388)', '', '', '﴿ رب أوۡزعۡني أنۡ أشۡكر نعۡمتك ٱلتي أنۡعمۡت علي وعلى ولدي وأنۡ أعۡمل صلحا ترۡضىه وأدۡخلۡني برحۡمتك في عبادك ٱلصلحين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (726, 82, 3, 'QuranText[(71:28:28)]', 1, 'الورد الثاني. [نوح: ٢٨]. (ص388)', '', '', '712828', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (628, 82, 4, 'QuranText[(14:40:41)]', 1, 'الورد الثاني. [إبراهيم: ٤٠، ٤١]. (ص388)', '', '', '144041', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (629, 82, 5, '﴿ رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي صَغِيرٗا ﴾', 1, 'الورد الثاني. [الإسراء: ٢٤]. (ص388)', '', '', '﴿ رب ٱرۡحمۡهما كما ربياني صغيرا ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1993, 82, 6, 'اللَّهُمَّ إنِّي أسألُكَ بأنَّ لَكَ الحمدَ، لا إلهَ إلَّا أنتَ وحدَكَ، لا شريكَ لكَ، المَنَّانُ، يا بديعَ السماواتِ والأرضِ، يا ذا الجلالِ والإكرامِ، يا حيُّ يا قيُّومُ، إنِّي أسألُكَ الجَنَّةَ، وأعوذُ بِكَ من النَّارِ.', 1, 'الورد الثاني. (ص389)', '', '', 'اللهم إني أسألك بأن لك الحمد لا إله إلا أنت وحدك لا شريك لك المنان يا بديع السماوات والأرض يا ذا الجلال والإكرام يا حي يا قيوم إني أسألك الجنة وأعوذ بك من النار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (611, 82, 7, 'لا إلهَ إلا اللهُ الحليمُ الكريمُ، لا إلهَ إلا اللهُ العليُّ العظيمُ، لا إله إلا اللهُ ربُّ السماواتِ السَّبعِ، وربُّ العرشِ الكريم.', 1, 'الورد الثاني. (ص389)', '', '', 'لا إله إلا الله الحليم الكريم لا إله إلا الله العلي العظيم لا إله إلا الله رب السماوات السبع ورب العرش الكريم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (657, 82, 8, 'اللَّهُمَّ إني أسألُكَ العفوَ والعافيةَ في الدُّنيا والآخِرة.', 1, 'الورد الثاني. (ص389)', '', '', 'اللهم إني أسألك العفو والعافية في الدنيا والآخرة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (699, 82, 9, 'اللَّهُمَّ إني أسألُكَ من فضلِكَ ورحمتِكَ، فإنه لا يملكُها إلا أنتَ.', 1, 'الورد الثاني. (ص389)', '', '', 'اللهم إني أسألك من فضلك ورحمتك فإنه لا يملكها إلا أنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (751, 82, 10, 'اللَّهُمَّ أنتَ رَبِّي، وأنا عبدُكَ، ظَلَمْتُ نفسي، واعترفتُ بذنبي يا ربِّ، فاغفِرْ لي ذنبي، إنكَ أنتَ ربي، إنه لا يغفرُ الذنبَ إلا أنتَ.', 1, 'الورد الثاني. (ص389)', '', '', 'اللهم أنت ربي وأنا عبدك ظلمت نفسي واعترفت بذنبي يا رب فاغفر لي ذنبي إنك أنت ربي إنه لا يغفر الذنب إلا أنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (736, 82, 11, 'ربِّ اغفِر لي خطيئتي يومَ الدين.', 1, 'الورد الثاني. (ص389)', '', '', 'رب اغفر لي خطيئتي يوم الدين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (769, 82, 12, 'رَبِّ أَعِنِّي، ولا تُعِنْ عَلَيَّ، وانصُرْني، ولا تَنْصُرْ عَلَيَّ، وامْكُرْ لِي، ولا تَمْكُرْ عَلَيَّ، واهْدِنِي، وَيَسِّرِ الهُدَى لي، وانصرني على مَنْ بَغَى عَلَيَّ، رَبِّ اجعلني لك ذكَّارًا، لك شكَّارًا، لك رَهَّابًا، لَكَ مِطْواعًا، لكَ مُخْبِتًا، إليكَ أوَّاهًا مُنِيبًا، رَبِّ تَقَبَّلْ تَوْبَتِي، وَاغْسِلْ حَوْبَتِي، وَأَجِبْ دَعْوَتِي، وثَبِّتْ حُجَّتِي، واهْدِ قَلْبِي، وسَدِّدْ لِساني، واسْلُلْ سَخِيمَةَ صدري.', 1, 'الورد الثاني. (ص390)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1994, 82, 13, 'اللهم إنِّي أعوذُ برضاكَ مِن سَخَطِكَ، وأعوذُ بمعافاتِكَ من عُقوبتِكَ، وأعوذُ بِكَ مِنْكَ، لا أُحْصِي ثناءً عليك، أنتَ كما أثنيتَ على نفْسِكَ.', 1, 'الورد الثاني. (ص391)', '', '', 'اللهم إني أعوذ برضاك من سخطك وأعوذ بمعافاتك من عقوبتك وأعوذ بك منك لا أحصي ثناء عليك أنت كما أثنيت على نفسك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (654, 82, 14, 'اللهم إني أعوذُ بِكَ من زَوَالِ نِعْمَتِكَ، وَتَحَوُّلِ عافيتِكَ، وفُجَاءَةِ نِقْمَتِكَ، وجميعِ سُخْطِكَ.', 1, 'الورد الثاني. (ص391)', '', '', 'اللهم إني أعوذ بك من زوال نعمتك وتحول عافيتك وفجاءة نقمتك وجميع سخطك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (653, 82, 15, 'اللهم أصلِحْ لي دينيَ الذي هو عِصْمَةُ أمري، وأصلح لي دنيايَ التي فيها مَعاشي، وأصلِحْ لي آخِرَتي التي فيها مَعادي، واجعلِ الحياةَ زيادةً لي في كُلِّ خَيرٍ، واجعلِ الموتَ راحةً لي من كُلِّ شَرٍّ.', 1, 'الورد الثاني. (ص391)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (715, 82, 16, 'اللهُمَّ أَعِنَّا على شُكْرِكَ، وذِكْرِكَ، وحُسْنِ عبادتِك.', 1, 'الورد الثاني. [الصحيحة: ٨٤٤]. (ص391)', '', '', 'اللهم أعنا على شكرك وذكرك وحسن عبادتك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (802, 82, 17, 'اللهم إني أعوذ بك أن أُشْرِكَ بك وأنا أعلم، وأستغفرك لما لا أعلم.', 1, 'الورد الثاني. (ص392)', '', '', 'اللهم إني أعوذ بك أن أشرك بك وأنا أعلم وأستغفرك لما لا أعلم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (806, 82, 18, 'اللهم إني عبدُكَ، وابنُ عبدِكَ، وابنُ أَمَتِكَ، في قبضتِكَ، ناصيتي بيدك، ماضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قضاؤكَ، أسألُك بِكُلِّ اسمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ أو أنزلْتَهُ في كتابِكَ، أو عَلَّمْتَهُ أحدًا من خَلْقِكَ، أو استأثرتَ به في عِلْمِ الغيبِ عِنْدَكَ أن تجعلَ القرآنَ العظيمَ ربيعَ قلبي، ونورَ صدري، وجِلاءَ حُزني، وَذَهَابَ همِّي.', 1, 'الورد الثاني. (ص392)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1995, 82, 19, 'اللَّهُمَّ عَلِّمْني الكتابَ، والحِكْمَةَ، وفَقِّهْني في الدِّين.', 1, 'الورد الثاني. (ص392)', '', '', 'اللهم علمني الكتاب والحكمة وفقهني في الدين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1996, 82, 20, 'اللهم إني أسألك العافية.', 1, 'الورد الثاني. (ص392)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (836, 82, 21, 'اللهم صَلِّ على مُحمدٍ، وعلى آلِ محمدٍ، وبارِكْ على محمدٍ، وعلى آلِ محمد، كما صليتَ، وباركتَ على إبراهيمَ، وآلِ إبراهيمَ، إنَّك حميدٌ مجيد.', 1, 'الورد الثاني. (ص393)', '', '', 'اللهم صل على محمد وعلى آل محمد وبارك على محمد وعلى آل محمد كما صليت وباركت على إبراهيم وآل إبراهيم إنك حميد مجيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (646, 83, 1, 'QuranText[(3:193:194)]', 1, 'الورد الثالث. [آل عمران: ١٩٣، ١٩٤]. (ص394)', '', '', '3193194', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (610, 83, 2, '﴿ أَنتَ وَلِيُّنَا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَاۖ وَأَنتَ خَيۡرُ ٱلۡغَٰفِرِينَ ١٥٥ وَٱكۡتُبۡ لَنَا فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ إِنَّا هُدۡنَآ إِلَيۡكَۚ ﴾', 1, 'الورد الثالث. [الأعراف: ١٥٥، ١٥٦]. (ص394)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1997, 83, 3, '﴿ سُبۡحَٰنَكَ تُبۡتُ إِلَيۡكَ وَأَنَا۠ أَوَّلُ ٱلۡمُؤۡمِنِينَ ﴾', 1, 'الورد الثالث. [الأعراف: ١٤٣]. (ص394)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1998, 83, 4, '«لا إله إلا اللهُ، واللهُ أكبرُ، لا إله إلا الله وحدَه، لا إله إلا الله، لا شريكَ له، لا إله إلا الله، له الملكُ، وله الحمدُ، لا إله إلا الله، ولا حَوْلَ ولا قوَّةَ إلَّا بالله».', 1, 'الورد الثالث. (ص395)', '', '', '«لا إله إلا الله والله أكبر لا إله إلا الله وحده لا إله إلا الله لا شريك له لا إله إلا الله له الملك وله الحمد لا إله إلا الله ولا حول ولا قوة إلا بالله»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1999, 83, 5, 'يا ربِّ! أنتَ أنتَ، وأنا أنا، أنتَ العَوَّادُ بالمغفرةِ، وأنَا العوَّادُ بالذُّنوب.', 1, 'الورد الثالث. [«السلسلة الصحيحة» (٣٢٣١)]. (ص395)', '', '', 'يا رب! أنت أنت وأنا أنا أنت العواد بالمغفرة وأنا العواد بالذنوب', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2000, 83, 6, 'اللهم إني أسألُكَ بأني أشهدُ أنك أنت اللهُ الذي لا إله إلا أنت، الأحدُ الصَّمَدُ، الذي لم يَلِدْ ولم يُولَدْ ولم يكن له كُفُوًا أحد، أن تغفرَ لي ذنوبي، إنك أنت الغفورُ الرحيمُ.', 1, 'الورد الثالث. (ص395)', '', '', 'اللهم إني أسألك بأني أشهد أنك أنت الله الذي لا إله إلا أنت الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفوا أحد أن تغفر لي ذنوبي إنك أنت الغفور الرحيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (773, 83, 7, 'اللهم إني ظلمتُ نفسي ظُلمًا كثيرًا، ولا يغفر الذنوبَ إلا أنتَ، فاغفر لي مغفرةً مِن عِنْدِكَ، وارحمني، إنك أنت الغفورُ الرحيم.', 1, 'الورد الثالث. (ص395)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2001, 83, 8, 'اللهم باعِدْ بيني وبين خطايايَ كما باعدتَ بين المشرقِ والمغرب، اللهم نَقِّنِي مِنْ خطاياي كما يُنَقَّى الثوبُ الأبيضُ من الدَّنَسِ، اللهم اغسلني من خطاياي بالماء والثلج والبَرَد.', 1, 'الورد الثالث. (ص396)', '', '', 'اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس اللهم اغسلني من خطاياي بالماء والثلج والبرد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2002, 83, 9, 'اللهم اغفر لي ما قَدَّمْتُ، وما أَخَّرْتُ، وما أسررتُ وما أعلنتُ، وما أسرفتُ، وما أنتَ أعلمُ به مني، أنت المقدِّمُ، وأنت المؤخِّرُ، لا إله إلا أنت.', 1, 'الورد الثالث. (ص397–398)', '', '', 'اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أسرفت وما أنت أعلم به مني أنت المقدم وأنت المؤخر لا إله إلا أنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2003, 83, 10, 'اللهم اغفر لي ذنبي كُلَّه، ودِقَّه وجِلَّه، وأوله وآخِرَه، وعلانِيَتَهُ وسِرَّه.', 1, 'الورد الثالث. (ص398)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (613, 83, 11, 'اللهم إني أسألُكَ من الخيرِ كُلِّهِ، عَاجِلِهِ وآجِلِهِ، مَا عَلِمْتُ منه، وما لم أعلم، وأعوذُ بكَ من الشَّرِّ كُلِّهِ، عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْتُ منه، وما لم أعلمْ، اللهم إني أسألك الجنةَ، وما قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَو عَمَل، وأعوذُ بك من النَّارِ، وما قرَّب إليها من قول أو عمل، اللهم إني أسألك من خير ما سألك عبدُكَ ورسولُك محمد ﷺ، وأعوذ بك من شَرِّ ما استعاذَكَ منه عبدُكَ ورسولُك محمدٌ ﷺ، وأسألك ما قضيتَ لِي مِنْ أَمْرٍ أن تجعلَ عاقِبَتَهُ لِي رَشَدًا.', 1, 'الورد الثالث. (ص398)', '', '', 'اللهم إني أسألك من الخير كله عاجله وآجله ما علمت منه وما لم أعلم وأعوذ بك من الشر كله عاجله وآجله ما علمت منه وما لم أعلم اللهم إني أسألك الجنة وما قرب إليها من قول أو عمل وأعوذ بك من النار وما قرب إليها من قول أو عمل اللهم إني أسألك من خير ما سألك عبدك ورسولك محمد وأعوذ بك من شر ما استعاذك منه عبدك ورسولك محمد وأسألك ما قضيت لي من أمر أن تجعل عاقبته لي رشدا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (732, 83, 12, 'اللهم إني أعوذُ بك من العجزِ والكَسَلِ، والجُبْنِ والبُخْلِ، والهَرَمِ، وعذابِ القبر، اللهم آتِ نفسي تقواها، وزَكِّها أنت خَيْرُ مَن زَكَّاها، أنت وليُّها ومولاها، اللهم إني أعوذ بك من علمٍ لا ينفع، ومن قلبٍ لا يخشع، ومن نفسٍ لا تشبع، ومن دعوةٍ لا يُستجاب لها.', 1, 'الورد الثالث. (ص399)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (799, 83, 13, 'اللهم إني أعوذ بك من يومِ السُّوء، ومن ليلةِ السُّوء، ومن ساعةِ السوء، ومن صاحبِ السُّوء، ومن جارِ السُّوءِ في دَارِ المُقامَةِ.', 1, 'الورد الثالث. (ص399)', '', '', 'اللهم إني أعوذ بك من يوم السوء ومن ليلة السوء ومن ساعة السوء ومن صاحب السوء ومن جار السوء في دار المقامة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (632, 83, 14, 'اللهم إني أسألك فِعْلَ الخيراتِ، وتَرْكَ المنكرات، وحُبَّ المساكين، وأن تغفرَ لي وترحمَني، وإذا أردتَ فِتنةَ قومٍ فتوفَّني غَيْرَ مفتونٍ، أسألُكَ حُبَّكَ، وحُبَّ مَنْ يُحِبُّكَ، وحُبَّ عَمَلٍ يُقَرِّبُ إلى حُبِّك.', 1, 'الورد الثالث. (ص399)', '', '', 'اللهم إني أسألك فعل الخيرات وترك المنكرات وحب المساكين وأن تغفر لي وترحمني وإذا أردت فتنة قوم فتوفني غير مفتون أسألك حبك وحب من يحبك وحب عمل يقرب إلى حبك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (852, 83, 15, 'اللهم إني أسألُكَ المعافاةَ في الدُّنيا والآخرة.', 1, 'الورد الثالث. (ص400)', '', '', 'اللهم إني أسألك المعافاة في الدنيا والآخرة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2004, 83, 16, 'اللهم لا تُخْزِنِي يومَ القيامةِ.', 1, 'الورد الثالث. [المُسنَد: ١٨٠٥٦]. (ص400)', '', '', 'اللهم لا تخزني يوم القيامة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2005, 83, 17, 'اللهم إني أسألُكَ الجَنَّةَ، وأعوذُ بِكَ مِنَ النَّار.', 1, 'الورد الثالث. (ص400)', '', '', 'اللهم إني أسألك الجنة وأعوذ بك من النار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (714, 83, 18, 'اللهم هَبِ المُسيئينَ مِنَّا للمُحْسِنِينَ، وأَعْطِ مُحْسِنَنَا ما سَأَلَ.', 1, 'الورد الثالث. (ص400)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2006, 83, 19, 'اللهم أَنْجِ المستَضْعَفينَ من المؤمنين.', 1, 'الورد الثالث. (ص401)', '', '', 'اللهم أنج المستضعفين من المؤمنين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2007, 83, 20, 'اللهم صَلِّ على مُحَمَّدٍ وعلى أَهْلِ بيتِه، وعلى أزواجِه وذُرِّيَّتِه، كما صَلَّيْتَ على آلِ إبراهيمَ، إنك حميدٌ مجيدٌ، وبَارِكْ على محمدٍ، وعلى آلِ بيتِه، وعلى أزواجِه وذُرِّيَّتِه، كما باركت على آلِ إبراهيمَ، إنك حميدٌ مجيد.', 1, 'الورد الثالث. (ص401)', '', '', 'اللهم صل على محمد وعلى أهل بيته وعلى أزواجه وذريته كما صليت على آل إبراهيم إنك حميد مجيد وبارك على محمد وعلى آل بيته وعلى أزواجه وذريته كما باركت على آل إبراهيم إنك حميد مجيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (606, 84, 1, 'QuranText[(3:53:53)]', 1, 'الورد الرابع. [آل عمران: ٥٣]. (ص402)', '', '', '35353', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (688, 84, 2, '﴿ رَبِّ إِنِّي لِمَآ أَنزَلۡتَ إِلَيَّ مِنۡ خَيۡرٖ فَقِيرٞ ﴾', 1, 'الورد الرابع. [القصص: ٢٤]. (ص402)', '', '', '﴿ رب إني لما أنزلۡت إلي منۡ خيۡر فقير ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2008, 84, 3, 'QuranText[(37:100:100)]', 1, 'الورد الرابع. [الصافات: ١٠٠]. (ص402)', '', '', '37100100', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2009, 84, 4, '﴿ رَبِّ هَبۡ لِي مِن لَّدُنكَ ذُرِّيَّةٗ طَيِّبَةًۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ ﴾', 1, 'الورد الرابع. [آل عمران: ٣٨]. (ص402)', '', '', '﴿ رب هبۡ لي من لدنك ذرية طيبةۖ إنك سميع ٱلدعاء ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2010, 84, 5, 'لا إله إلا اللهُ العظيمُ الحليم، لا إله إلَّا الله ربُّ العرشِ العظيم، لا إله إلا الله ربُّ السماواتِ والأرضِ، لا إله إلا اللهُ ربُّ العرشِ الكريم.', 1, 'الورد الرابع. (ص402)', '', '', 'لا إله إلا الله العظيم الحليم لا إله إلا الله رب العرش العظيم لا إله إلا الله رب السماوات والأرض لا إله إلا الله رب العرش الكريم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (713, 84, 6, 'اللهم اقْسِمْ لَنَا من خَشْيَتِكَ ما تحولُ به بيننا وبين معاصيك، ومن طاعتك ما تُبَلِّغُنا به جنتَك، ومن اليقينِ ما تُهَوِّنُ به علينا مصائبَ الدُّنيا، ومَتِّعْنا بأسماعِنا، وأبصارِنا، وقُوَّتِنا ما أحييتَنا، واجعلْه الوَارِثَ مِنَّا، واجعل ثأرَنا على مَن ظَلَمَنَا، وانصُرْنا على مَن عادانا، ولا تجعلْ مصيبتَنا في دينِنا، ولا تجعلِ الدنيا أكبرَ هَمِّنا، ولا مَبْلَغَ عِلْمِنا، ولا تُسَلِّطْ علينا من لا يرحمُنا.', 1, 'الورد الرابع. (ص402–403)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2011, 84, 7, 'اللهم اغفر لي ما أسررتُ وما أعلنتُ.', 1, 'الورد الرابع. (ص403)', '', '', 'اللهم اغفر لي ما أسررت وما أعلنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (734, 84, 8, 'اللهم اغفر لي ذنبي، وخطئي وعَمْدي، اللهم إني أستهديك لأرشَدِ أمري، وأعوذُ بك من شَرِّ نفسي.', 1, 'الورد الرابع. (ص403)', '', '', 'اللهم اغفر لي ذنبي وخطئي وعمدي اللهم إني أستهديك لأرشد أمري وأعوذ بك من شر نفسي', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2012, 84, 9, 'ربِّ أسألك العافيةَ والمعافاةَ في الدنيا والآخرة.', 1, 'الورد الرابع. (ص403)', '', '', 'رب أسألك العافية والمعافاة في الدنيا والآخرة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (712, 84, 10, 'اللهم ربنا آتنا في الدُّنيا حسنة، وفي الآخرةِ حسنةً، وَقِنا عذابَ النَّارِ.', 1, 'الورد الرابع. (ص403)', '', '', 'اللهم ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (805, 84, 11, 'اللهم اجعلْني مِفْتَاحًا للخيرِ مِغْلاقًا للشرِّ، ولا تجعلني مِفْتاحًا للشر مِغْلاقًا للخير.', 1, 'الورد الرابع. (ص404)', '', '', 'اللهم اجعلني مفتاحا للخير مغلاقا للشر ولا تجعلني مفتاحا للشر مغلاقا للخير', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2013, 84, 12, 'اللهم لك الحمدُ كُلُّه، اللهم لا قابضَ لما بَسَطتَ، ولا باسطَ لما قبضتَ، ولا هادِيَ لِمَا أَضْلَلْتَ، ولا مُضِلَّ لِمَن هَدَيْتَ، ولا مُعْطِيَ لما منَعْت، ولا مَانِعَ لما أَعْطَيْتَ، ولا مُقَرِّبَ لما باعَدْتَ، وَلا مُبَاعِدَ لما قَرَّبْتَ، اللهُمَّ ابْسُطْ علينا مِنْ بَرَكَاتِكَ ورَحْمَتِكَ وفَضْلِكَ ورِزْقِكَ، اللهم إني أسألُكَ النَّعيمَ المقيمَ الذي لا يَحُولُ ولا يزول، اللهُمَّ إني أسألك النعيمَ يَوْمَ العَيْلَةِ، والأمنَ يومَ الخوفِ، اللهُمَّ إني عائذٌ بِكَ مِنْ شَرِّ ما أَعْطَيْتَنَا وَشَرِّ ما مَنَعْتَنا، اللهُمَّ حَبِّبْ إلينا الإيمانَ، وزَيِّنْهُ في قلوبنا، وكرِّهْ إلينا الكفرَ والفسوقَ والعصيانَ، واجعلنا من الراشدين، اللهُمَّ تَوَفَّنا مسلمين، وأحْيِنا مسلمين، وألحِقنا بالصالحين غَيْرَ خَزايا ولا مفتونين، اللهُمَّ قَاتِلِ الكَفَرَةَ الَّذين يُكَذِّبُونَ رُسُلَكَ، وَيَصُدُّون عن سبيلِكَ، واجْعَل عليهم رِجْزَكَ وعَذَابَكَ، اللهُمَّ قَاتِلِ الكفرةَ الذين أُوتُوا الكتابَ، إلهَ الحقِّ.', 1, 'الورد الرابع. (ص404–405)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2014, 84, 13, 'اللهم أنت المَلِكُ، لا إله إلا أنت، سبحانك وبحمدك، أنت ربي، وأنا عبدُك، ظلمتُ نفسي، واعترفتُ بذنبي، فاغفر لي ذنوبي جميعًا، إنه لا يغفر الذنوبَ إلا أنت، واهْدِنِي لأحسنِ الأخلاقِ، لا يَهْدِي لأحسنِها إلا أنتَ، واصرِفْ عني سَيِّئَها، لا يصرفُ عني سيئَها إلا أنت، لَبَّيْكَ وسَعْدَيْكَ والخيرُ كُلُّه في يديك، والشرُّ ليس إليك، والمَهْدِيُّ مَن هَدَيْتَ، أنا بك وإليك، لا مَنْجا ولا ملجأ مِنكَ إلا إليك، تباركتَ وتعاليتَ، أستغفرُك، وأتوبُ إليك.', 1, 'الورد الرابع. (ص405)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (770, 84, 14, 'اللهم إني أعوذ بك من فتنةِ النار، وعذابِ النار، وفتنةِ القبر، وعذابِ القبر، ومن شَرِّ فتنةِ الغِنَى، ومن شرِّ فتنةِ الفقر، وأعوذ بك من شرِّ فتنةِ المسيح الدَّجَّال، اللهُمَّ اغْسِلْ خطايايَ بماءِ الثَّلْجِ والبَرَدِ، ونَقِّ قلبي من الخطايا كما نَقَّيتَ الثوبَ الأبيضَ من الدَّنَسِ، وباعِدْ بيني وبين خطايايَ كما باعدْتَ بين المشرقِ والمغربِ، اللهم إني أعوذُ بِكَ من الكَسَلِ والهَرَمِ، والمأثَمِ والمغرم.', 1, 'الورد الرابع. (ص405–406)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2015, 84, 15, 'اللهُمَّ صَلِّ على مُحَمَّدٍ عبدِكَ ورسولِكَ، كما صَلَّيْتَ على آلِ إبراهيم، وبارِكْ على محمدٍ عبدِكَ ورسولِكَ، وعلى آلِ محمدٍ، كما باركتَ على إبراهيمَ، وعلى آلِ إبراهيمَ.', 1, 'الورد الرابع. (ص406)', '', '', 'اللهم صل على محمد عبدك ورسولك كما صليت على آل إبراهيم وبارك على محمد عبدك ورسولك وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2016, 93, 1, 'تعالى ﴿ ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۖ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡكَرِيمِ ﴾', 1, 'الورد الخامس. [المؤمنون: ١١٦]. (ص407)', '', '', 'تعالى ﴿ ٱلله ٱلۡملك ٱلۡحقۖ لا إله إلا هو رب ٱلۡعرۡش ٱلۡكريم ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2017, 93, 2, '﴿ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي لَمۡ يَتَّخِذۡ وَلَدٗا وَلَمۡ يَكُن لَّهُۥ شَرِيكٞ فِي ٱلۡمُلۡكِ وَلَمۡ يَكُن لَّهُۥ وَلِيّٞ مِّنَ ٱلذُّلِّۖ ﴾', 1, 'الورد الخامس. [الإسراء: ١١١]. (ص407)', '', '', '﴿ ٱلۡحمۡد لله ٱلذي لمۡ يتخذۡ ولدا ولمۡ يكن لهۥ شريك في ٱلۡملۡك ولمۡ يكن لهۥ ولي من ٱلذلۖ ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2018, 93, 3, 'الله أكبر، الله أكبر، الله أكبر كبيرًا.', 1, 'الورد الخامس. (ص407)', '', '', 'الله أكبر الله أكبر الله أكبر كبيرا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (847, 93, 4, '﴿ رَبَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ ﴾', 1, 'الورد الخامس. [المؤمنون: ١٠٩]. (ص407)', '', '', '﴿ ربنا ءامنا فٱغۡفرۡ لنا وٱرۡحمۡنا وأنت خيۡر ٱلرحمين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (687, 93, 5, '﴿ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي فَٱغۡفِرۡ لِي ﴾', 1, 'الورد الخامس. [القصص: ١٦]. (ص407)', '', '', '﴿ رب إني ظلمۡت نفۡسي فٱغۡفرۡ لي ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (846, 93, 6, '﴿ لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ ﴾', 1, 'الورد الخامس. [الأنبياء: ٨٧]. (ص407)', '', '', '﴿ لا إله إلا أنت سبۡحنك إني كنت من ٱلظلمين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (649, 93, 7, '﴿ رَبِّ ٱشۡرَحۡ لِي صَدۡرِي ٢٥ وَيَسِّرۡ لِيٓ أَمۡرِي ﴾', 1, 'الورد الخامس. [طه: ٢٥، ٢٦]. (ص407)', '', '', '﴿ رب ٱشۡرحۡ لي صدۡري ٢٥ ويسرۡ لي أمۡري ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (708, 93, 8, '﴿ رَبَّنَا ٱصۡرِفۡ عَنَّا عَذَابَ جَهَنَّمَۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا ٦٥ إِنَّهَا سَآءَتۡ مُسۡتَقَرّٗا وَمُقَامٗا ﴾', 1, 'الورد الخامس. [الفرقان: ٦٥، ٦٦]. (ص408)', '', '', '﴿ ربنا ٱصۡرفۡ عنا عذاب جهنمۖ إن عذابها كان غراما ٦٥ إنها ساءتۡ مسۡتقرا ومقاما ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (690, 93, 9, '﴿ رَبِّ ٱبۡنِ لِي عِندَكَ بَيۡتٗا فِي ٱلۡجَنَّةِ ﴾', 1, 'الورد الخامس. [التحريم: ١١]. (ص408)', '', '', '﴿ رب ٱبۡن لي عندك بيۡتا في ٱلۡجنة ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2019, 93, 10, 'لا إله إلا اللهُ الواحدُ القهَّارُ، ربُّ السماواتِ والأرضِ وما بينهما العزيزُ الغفَّارُ.', 1, 'الورد الخامس. (ص408)', '', '', 'لا إله إلا الله الواحد القهار رب السماوات والأرض وما بينهما العزيز الغفار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (834, 93, 11, 'اللهم إني أسألك يا أللهُ الواحدُ الأحدُ الصمدُ، الذي لم يلد، ولم يُولَدْ، ولم يكن له كُفُوًا أحدٌ، أن تغفرَ لي ذُنُوبي، إنك أنتَ الغفورُ الرحيم.', 1, 'الورد الخامس. (ص408)', '', '', 'اللهم إني أسألك يا ألله الواحد الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفوا أحد أن تغفر لي ذنوبي إنك أنت الغفور الرحيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (697, 93, 12, 'اللهم إني أسألك اليقينَ والمعافاة.', 1, 'الورد الخامس. (ص408)', '', '', 'اللهم إني أسألك اليقين والمعافاة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (735, 93, 13, 'اللهم اغفر لي، وارحمني، واهدني، وعافني، وارزقني.', 1, 'الورد الخامس. (ص408)', '', '', 'اللهم اغفر لي وارحمني واهدني وعافني وارزقني', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (803, 93, 14, 'اللهم اغفر لي ذنبي، وَوَسِّع لي في داري، وبارك لي فيما رزقتني.', 1, 'الورد الخامس. (ص408)', '', '', 'اللهم اغفر لي ذنبي ووسع لي في داري وبارك لي فيما رزقتني', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2020, 93, 15, 'اللهم ثبتني، واجعلني هاديًا مهديًّا.', 1, 'الورد الخامس. (ص409)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2021, 93, 16, 'اللهم اصْرِفْ عني السوءَ والفحشاءَ، واجعلني من عبادِكَ عني المخلَصين.', 1, 'الورد الخامس. (ص409)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (633, 93, 17, 'اللهم إني أعوذ بك من شَرِّ ما عَمِلْتُ، ومن شر ما لم أعمل.', 1, 'الورد الخامس. (ص409)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (800, 93, 18, 'اللهم إني أعوذ بك من قلبٍ لا يخشع، ومن دعاءٍ لا يُسْمَعُ، ومن نفسٍ لا تشبع، ومن علمٍ لا ينفع، أعوذ بك من هؤلاء الأربع.', 1, 'الورد الخامس. (ص409)', '', '', 'اللهم إني أعوذ بك من قلب لا يخشع ومن دعاء لا يسمع ومن نفس لا تشبع ومن علم لا ينفع أعوذ بك من هؤلاء الأربع', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (855, 93, 19, 'اللهم إني أعوذ بك من شَرِّ سمعي، ومن شر بصري، ومن شر لساني، ومن شر قلبي، ومن شر مَنِيِّي.', 1, 'الورد الخامس. (ص409)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2022, 93, 20, 'اللهم اغفِرْ ذَنْبِي، وطَهِّر قلبي، وحَصِّنْ فَرْجِي.', 1, 'الورد الخامس. (ص410)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2023, 93, 21, 'اللهم إنِّي أعوذُ بك من الهَمِّ والحَزَنِ، والعجزِ والكسل، والجُبنِ والبُخلِ، وضَلَعِ الدَّيْنِ، وغَلَبَةِ الرجال.', 1, 'الورد الخامس. (ص410)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2024, 93, 22, 'اللهم إنِّي أعوذُ بِكَ من الجُبْنِ، والبُخْلِ، وسوءِ العُمُرِ، وفتنةِ الصَّدْرِ، وعذابِ القبر.', 1, 'الورد الخامس. (ص410)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2025, 93, 23, 'اللهم إنِّي أعوذُ بِكَ من ضِيقِ الدُّنيا وضِيقِ يومِ القيامة.', 1, 'الورد الخامس. [أصله دعاء الاستفتاح في التهجد]. (ص411)', '', '', 'اللهم إني أعوذ بك من ضيق الدنيا وضيق يوم القيامة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2026, 93, 24, 'اللهم اسقِني مِن سَلْسَبيلِ الجنة.', 1, 'الورد الخامس. [دعاء أم المؤمنين عائشة لعبد الرحمن بن عوف رضي الله عنهما]. (ص411)', '', '', 'اللهم اسقني من سلسبيل الجنة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (807, 93, 25, 'اللهم صَلِّ على محمدٍ وعلى أهلِ بيته، وعلى أزواجه وذُريته، كما صليتَ على آلِ إبراهيمَ، إنَّك حميدٌ مجيدٌ، وبارِكْ على محمدٍ وعلى آلِ بيته، وعلى أزواجِهِ وذُريتِهِ، كما باركتَ على آلِ إبراهيمَ، إنَّك حميدٌ مجيد.', 1, 'الورد الخامس. (ص411)', '', '', 'اللهم صل على محمد وعلى أهل بيته وعلى أزواجه وذريته كما صليت على آل إبراهيم إنك حميد مجيد وبارك على محمد وعلى آل بيته وعلى أزواجه وذريته كما باركت على آل إبراهيم إنك حميد مجيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (833, 86, 1, '﴿ رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ﴾', 1, 'الورد السادس. [الأعراف: ٢٣]. (ص412)', '', '', '﴿ ربنا ظلمۡنا أنفسنا وإن لمۡ تغۡفرۡ لنا وترۡحمۡنا لنكونن من ٱلۡخسرين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2027, 86, 2, '﴿ لَئِن لَّمۡ يَرۡحَمۡنَا رَبُّنَا وَيَغۡفِرۡ لَنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ﴾', 1, 'الورد السادس. [الأعراف: ١٤٩]. (ص412)', '', '', '﴿ لئن لمۡ يرۡحمۡنا ربنا ويغۡفرۡ لنا لنكونن من ٱلۡخسرين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (626, 86, 3, '﴿ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ ﴾', 1, 'الورد السادس. [آل عمران: ١٦]. (ص412)', '', '', '﴿ ربنا إننا ءامنا فٱغۡفرۡ لنا ذنوبنا وقنا عذاب ٱلنار ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (747, 86, 4, '﴿ رَبَّنَا وَسِعۡتَ كُلَّ شَيۡءٖ رَّحۡمَةٗ وَعِلۡمٗا فَٱغۡفِرۡ لِلَّذِينَ تَابُواْ وَٱتَّبَعُواْ سَبِيلَكَ وَقِهِمۡ عَذَابَ ٱلۡجَحِيمِ ٧ رَبَّنَا وَأَدۡخِلۡهُمۡ جَنَّٰتِ عَدۡنٍ ٱلَّتِي وَعَدتَّهُمۡ وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّٰتِهِمۡۚ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ٨ وَقِهِمُ ٱلسَّيِّـَٔاتِۚ وَمَن تَقِ ٱلسَّيِّـَٔاتِ يَوۡمَئِذٖ فَقَدۡ رَحِمۡتَهُۥۚ وَذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴾', 1, 'الورد السادس. [غافر: ٧-٩]. (ص412)', '', '', '﴿ ربنا وسعۡت كل شيۡء رحۡمة وعلۡما فٱغۡفرۡ للذين تابوا وٱتبعوا سبيلك وقهمۡ عذاب ٱلۡجحيم ٧ ربنا وأدۡخلۡهمۡ جنت عدۡن ٱلتي وعدتهمۡ ومن صلح منۡ ءابائهمۡ وأزۡوجهمۡ وذريتهمۡۚ إنك أنت ٱلۡعزيز ٱلۡحكيم ٨ وقهم ٱلسياتۚ ومن تق ٱلسيات يوۡمئذ فقدۡ رحمۡتهۥۚ وذلك هو ٱلۡفوۡز ٱلۡعظيم ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (725, 86, 5, '﴿ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَصۡلِحۡ لِي فِي ذُرِّيَّتِيٓۖ إِنِّي تُبۡتُ إِلَيۡكَ وَإِنِّي مِنَ ٱلۡمُسۡلِمِينَ ﴾', 1, 'الورد السادس. [الأحقاف: ١٥]. (ص413)', '', '', '﴿ رب أوۡزعۡني أنۡ أشۡكر نعۡمتك ٱلتي أنۡعمۡت علي وعلى ولدي وأنۡ أعۡمل صلحا ترۡضىه وأصۡلحۡ لي في ذريتيۖ إني تبۡت إليۡك وإني من ٱلۡمسۡلمين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (709, 86, 6, '﴿ رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعۡيُنٖ وَٱجۡعَلۡنَا لِلۡمُتَّقِينَ إِمَامًا ﴾', 1, 'الورد السادس. [الفرقان: ٧٤]. (ص413)', '', '', '﴿ ربنا هبۡ لنا منۡ أزۡوجنا وذريتنا قرة أعۡين وٱجۡعلۡنا للۡمتقين إماما ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2028, 86, 7, 'اللهم لك الحمدُ، أنت نورُ السماواتِ والأرضِ ومَنْ فيهنَّ، ولك الحمدُ، أنت قيِّمُ السماواتِ والأرضِ ومَن فيهنَّ، ولك الحمدُ، أنت مَلِكُ السماواتِ والأرضِ ومن فيهنَّ، ولك الحمدُ، أنت الحقُّ، ووعدُك حقٌّ، وقولُك حقٌّ، ولقاؤكَ حقٌّ، والجنةُ حقٌّ، والنارُ حقٌّ، والساعةُ حقٌّ، والنبيُّون حقٌّ، ومحمدٌ حقٌّ، اللهم لك أسلمتُ، وعليك توكلتُ، وبك آمنتُ، وإليك أنبتُ، وبك خاصمتُ، وإليك حاكَمْتُ، أنت رَبُّنا، وإليكَ المصير، فاغفر لي ما قدَّمْتُ، وما أَخَّرْتُ، وما أسررتُ، وما أعلنتُ، وما أنت أعلمُ به مني، أنت المقدِّمُ، وأنت المؤخِّرُ، أنت إلهي لا إله إلا أنت، ولا حولَ ولا قوةَ إلا بك.', 1, 'الورد السادس. (ص413–414)', '', '', 'اللهم لك الحمد أنت نور السماوات والأرض ومن فيهن ولك الحمد أنت قيم السماوات والأرض ومن فيهن ولك الحمد أنت ملك السماوات والأرض ومن فيهن ولك الحمد أنت الحق ووعدك حق وقولك حق ولقاؤك حق والجنة حق والنار حق والساعة حق والنبيون حق ومحمد حق اللهم لك أسلمت وعليك توكلت وبك آمنت وإليك أنبت وبك خاصمت وإليك حاكمت أنت ربنا وإليك المصير فاغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أنت أعلم به مني أنت المقدم وأنت المؤخر أنت إلهي لا إله إلا أنت ولا حول ولا قوة إلا بك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2029, 86, 8, 'سبحانَ اللهِ وبحمدِه، أستغفرُ اللهَ وأتوبُ إليه.', 1, 'الورد السادس. (ص414)', '', '', 'سبحان الله وبحمده أستغفر الله وأتوب إليه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2030, 86, 9, 'اللهم اغفر لي ذنبي، وأدخِلْني يومَ القيامةِ مُدْخَلًا كريمًا.', 1, 'الورد السادس. (ص414)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2031, 86, 10, 'اللهم ربَّ جبرائيلَ وميكائيلَ، وربَّ إسرافيلَ، أعوذُ بك من حَرِّ النارِ، وعذابِ القبر.', 1, 'الورد السادس. (ص414)', '', '', 'اللهم رب جبرائيل وميكائيل ورب إسرافيل أعوذ بك من حر النار وعذاب القبر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2032, 86, 11, 'اللهم جَنِّبْني مُنكَراتِ الأخلاقِ والأهواءِ والأعمالِ والأدواءِ.', 1, 'الورد السادس. (ص414)', '', '', 'اللهم جنبني منكرات الأخلاق والأهواء والأعمال والأدواء', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (698, 86, 12, 'اللهم إني أسألك الهدى، والتُّقى، والعفافَ، والغِنى.', 1, 'الورد السادس. (ص414)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2033, 86, 13, 'اللهم إني أسألُكَ الثَّباتَ في الأمر، والعزيمةَ على الرُّشْدِ، وأسألُكَ مُوجِباتِ رحمتِكَ، وعزائمَ مغفرتِك، وأسألك شُكْرَ نعمتِك، وحُسْنَ عبادتِكَ، وأسألك قلبًا سليمًا، ولسانًا صادقًا، وأسألُكَ مِن خيرِ ما تَعْلَمُ، وأعوذُ بِكَ مِن شَرِّ ما تَعْلَمُ، وأستغفرك لما تعلمُ، إنَّكَ أنتَ علام الغيوب.', 1, 'الورد السادس. [«الصحيحة» (٣٢٢٨)]. (ص415)', '', '', 'اللهم إني أسألك الثبات في الأمر والعزيمة على الرشد وأسألك موجبات رحمتك وعزائم مغفرتك وأسألك شكر نعمتك وحسن عبادتك وأسألك قلبا سليما ولسانا صادقا وأسألك من خير ما تعلم وأعوذ بك من شر ما تعلم وأستغفرك لما تعلم إنك أنت علام الغيوب', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2034, 86, 14, 'اللهم إني أعوذ بعظمتِكَ أن أُغْتَالَ مِنْ تحتي.', 1, 'الورد السادس. (ص415)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (694, 86, 15, 'اللهم إني أعوذ بكَ من الجوعِ، فإنه بِئْسَ الضجيعُ، وأعوذ بك من الخيانة، فإنها بِئْسَتِ البطانةُ.', 1, 'الورد السادس. (ص415)', '', '', 'اللهم إني أعوذ بك من الجوع فإنه بئس الضجيع وأعوذ بك من الخيانة فإنها بئست البطانة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (733, 86, 16, 'اللهم إني أعوذ بك من الفقرِ والقِلَّةِ، والذِّلَّةِ، وأعوذ بك أن أَظْلِمَ أو أُظْلَمَ.', 1, 'الورد السادس. (ص415)', '', '', 'اللهم إني أعوذ بك من الفقر والقلة والذلة وأعوذ بك أن أظلم أو أظلم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2035, 86, 17, 'اللهم أكثِرْ مالي وولدي، وبارك لي فيما أعطيتني.', 1, 'الورد السادس. (ص415)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (693, 86, 18, 'اللهم اجعلْ أوسعَ رزقِكَ عليَّ عند كِبَرِ سِنِّي، وانقطاعِ عُمُري.', 1, 'الورد السادس. (ص416)', '', '', 'اللهم اجعل أوسع رزقك علي عند كبر سني وانقطاع عمري', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (857, 86, 19, 'اللهم حاسبني حسابًا يسيرًا.', 1, 'الورد السادس. (ص416)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (691, 86, 20, 'اللهم أحيني مِسكينًا، وأمِتْني مِسْكينًا، واحشُرْني في زُمْرَةِ المساكين.', 1, 'الورد السادس. (ص416)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2036, 86, 21, 'اللهُمَّ صُبَّ عَلَيَّ الخيرَ صَبًّا، ولا تَجْعَلْ عَيْشِي كَدًّا كَدًّا.', 1, 'الورد السادس. (ص416)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (752, 86, 22, 'اللهم صَلِّ على محمدٍ وعلى أزواجه وذُرِّيَّتِه، كما صليتَ على آلِ إبراهيمَ، وبارِكْ على مُحمدٍ وعلى أزواجه وذريته، كما باركت على آلِ إبراهيمَ، إنَّكَ حميدٌ مجيدٌ.', 1, 'الورد السادس. (ص416)', '', '', 'اللهم صل على محمد وعلى أزواجه وذريته كما صليت على آل إبراهيم وبارك على محمد وعلى أزواجه وذريته كما باركت على آل إبراهيم إنك حميد مجيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2037, 87, 1, '﴿ ... ٱللَّهُمَّ مَٰلِكَ ٱلۡمُلۡكِ تُؤۡتِي ٱلۡمُلۡكَ مَن تَشَآءُ وَتَنزِعُ ٱلۡمُلۡكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُۖ بِيَدِكَ ٱلۡخَيۡرُۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ٢٦ تُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِۖ وَتُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَتُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّۖ وَتَرۡزُقُ مَن تَشَآءُ بِغَيۡرِ حِسَابٖ ﴾', 1, 'الورد السابع. [آل عمران: ٢٦، ٢٧]. (ص417)', '', '', '﴿ ٱللهم ملك ٱلۡملۡك تؤۡتي ٱلۡملۡك من تشاء وتنزع ٱلۡملۡك ممن تشاء وتعز من تشاء وتذل من تشاءۖ بيدك ٱلۡخيۡرۖ إنك على كل شيۡء قدير ٢٦ تولج ٱليۡل في ٱلنهار وتولج ٱلنهار في ٱليۡلۖ وتخۡرج ٱلۡحي من ٱلۡميت وتخۡرج ٱلۡميت من ٱلۡحيۖ وترۡزق من تشاء بغيۡر حساب ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2038, 87, 2, 'اللهم ارزُقْنا ﴿ وَأَنتَ خَيۡرُ ٱلرَّٰزِقِينَ ﴾', 1, 'الورد السابع. [المائدة: ١١٤]. (ص417)', '', '', 'اللهم ارزقنا ﴿ وأنت خيۡر ٱلرزقين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (793, 87, 3, 'لا إله إلا اللهُ الحليمُ الكريمُ، لا إله إلا اللهُ العَلِيُّ العظيمُ، لا إله إلا اللهُ ربُّ السماواتِ السبعِ، وربُّ العرشِ الكريم.', 1, 'الورد السابع. (ص417)', '', '', 'لا إله إلا الله الحليم الكريم لا إله إلا الله العلي العظيم لا إله إلا الله رب السماوات السبع ورب العرش الكريم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2039, 87, 4, 'اللهم إنَّكَ عَفُوٌّ تُحِبُّ العفوَ، فاعفُ عَنِّي.', 1, 'الورد السابع. (ص417)', '', '', 'اللهم إنك عفو تحب العفو فاعف عني', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (727, 87, 5, 'لا إلهَ إلا أنتَ، سُبحانَكَ إني كُنتُ من الظالمين.', 1, 'الورد السابع. (ص418)', '', '', 'لا إله إلا أنت سبحانك إني كنت من الظالمين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2040, 87, 6, 'رَبِّ اغفِرْ وارحَمْ، إنَّك أنتَ الأَعَزُّ الأكرم.', 1, 'الورد السابع. [موقوف عن ابن مسعودٍ وابن عمر رضي الله عنهم]. (ص418)', '', '', 'رب اغفر وارحم إنك أنت الأعز الأكرم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (768, 87, 7, 'اللهم رَبِّ اغفِر لي خطيئتي وجهلي، وإسرافي في أمري، وما أنتَ أعلمُ به مني، اللهم اغفِر لي جِدِّي وهَزْلِي، وخَطَئِي وعَمْدِي، وكُلُّ ذلك عِنْدي، اللهُمَّ اغفِر لي ما قَدَّمْتُ، وما أَخَّرْتُ، وما أَسْرَرْتُ، وما أعلنتُ، وما أنتَ أعلمُ به مِنِّي، أنتَ المُقَدِّمُ، وأنتَ المؤخِّرُ، وأنتَ على كُلِّ شيءٍ قديرٌ.', 1, 'الورد السابع. (ص418)', '', '', 'اللهم رب اغفر لي خطيئتي وجهلي وإسرافي في أمري وما أنت أعلم به مني اللهم اغفر لي جدي وهزلي وخطئي وعمدي وكل ذلك عندي اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت وما أنت أعلم به مني أنت المقدم وأنت المؤخر وأنت على كل شيء قدير', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (695, 87, 8, 'اللهم بعلمِكَ الغيبَ، وقُدْرَتِكَ على الخَلْقِ، أحيِني ما عَلِمْتَ الحياةَ خيرًا لي، وتَوَفَّنِي إذا علمتَ الوفاةَ خيرًا لي، اللهُم وأسألُكَ خشيتَكَ في الغيبِ والشهادة، وأسألُكَ كلمةَ الحقِّ في الرضى والغضب، وأسألُك القَصْدَ في الفقرِ والغِنى، وأسألُكَ نعيمًا لا يَنفدُ، وأسألُك قُرَّةَ عينٍ لا تنقطعُ، وأسألُك الرِّضى بعدَ القضاءِ، وأسألُك بَرْدَ الْعَيْشِ بَعْدَ الموتِ، وأسألُك لَذَّةَ النظرِ إلى وجهِكَ، والشوقَ إلى لقائك، في غيرِ ضَرَّاءَ مُضِرَّةٍ، ولا فتنةٍ مُضِلَّة، اللهم زَيِّنَّا بزينةِ الإيمانِ، واجعلْنا هُدَاةً مُهْتَدِين.', 1, 'الورد السابع. (ص418–419)', '', '', 'اللهم بعلمك الغيب وقدرتك على الخلق أحيني ما علمت الحياة خيرا لي وتوفني إذا علمت الوفاة خيرا لي اللهم وأسألك خشيتك في الغيب والشهادة وأسألك كلمة الحق في الرضى والغضب وأسألك القصد في الفقر والغنى وأسألك نعيما لا ينفد وأسألك قرة عين لا تنقطع وأسألك الرضى بعد القضاء وأسألك برد العيش بعد الموت وأسألك لذة النظر إلى وجهك والشوق إلى لقائك في غير ضراء مضرة ولا فتنة مضلة اللهم زينا بزينة الإيمان واجعلنا هداة مهتدين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2041, 87, 9, 'اللهم اغفِرْ لي، واجعلني يومَ القيامةِ فوقَ كثيرٍ من خَلْقِكَ.', 1, 'الورد السابع. (ص419)', '', '', 'اللهم اغفر لي واجعلني يوم القيامة فوق كثير من خلقك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2042, 87, 10, 'اللهُمَّ اغفِرْ لي ذنبي، وأدخِلْني يومَ القيامةِ مُدْخَلًا كريمًا.', 1, 'الورد السابع. (ص419)', '', '', 'اللهم اغفر لي ذنبي وأدخلني يوم القيامة مدخلا كريما', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2043, 87, 11, 'اللهم اغفِرْ لنا وارحمنا، وآتِنا في الدنيا حَسَنَةً، وفي الآخرةِ حسنةً، وقِنَا عذابَ النار.', 1, 'الورد السابع. [من دُعَاءِ أَنَسِ بْنِ مَالِكٍ رضي الله عنه]. (ص419)', '', '', 'اللهم اغفر لنا وارحمنا وآتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2044, 87, 12, 'اللهم إني أسألك العافيةَ في الدنيا والآخرة.', 1, 'الورد السابع. (ص419)', '', '', 'اللهم إني أسألك العافية في الدنيا والآخرة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (692, 87, 13, 'اللهم اكْفِني بِحَلالِكَ عن حَرَامِكَ، وأَغْنِنِي بفضلِكَ عَمَّن سِواك.', 1, 'الورد السابع. (ص419)', '', '', 'اللهم اكفني بحلالك عن حرامك وأغنني بفضلك عمن سواك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2045, 87, 14, 'اللهم إني أعوذُ بك من قولٍ لا يُسمَعُ، وعملٍ لا يُرفَعُ، وقلبٍ لا يَخْشَعُ، وعلمٍ لا يَنفع.', 1, 'الورد السابع. (ص419)', '', '', 'اللهم إني أعوذ بك من قول لا يسمع وعمل لا يرفع وقلب لا يخشع وعلم لا ينفع', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2046, 87, 15, 'اللهم إني أعوذ بك من الكسل والهَرَم، والمَغْرَمِ والمأثم، وأعوذ بك من شرِّ المسيح الدجال، وأعوذ بك من عذابِ القبرِ، وأعوذ بك من عذاب النار.', 1, 'الورد السابع. (ص420)', '', '', 'اللهم إني أعوذ بك من الكسل والهرم والمغرم والمأثم وأعوذ بك من شر المسيح الدجال وأعوذ بك من عذاب القبر وأعوذ بك من عذاب النار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (771, 87, 16, 'اللهم مَنْ وَلِي مِنْ أمرِ أُمَّةِ محمدٍ ﷺ شيئًا فَشَقَّ عليهم، فاشْقُقْ عليه، ومن وَلِيَ مِنْ أمرِ أمةِ محمدٍ ﷺ شيئًا فَرفَقَ بهم، فارفُقْ به.', 1, 'الورد السابع. (ص420)', '', '', 'اللهم من ولي من أمر أمة محمد شيئا فشق عليهم فاشقق عليه ومن ولي من أمر أمة محمد شيئا فرفق بهم فارفق به', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2047, 87, 17, 'اللهُمَّ صَلِّ على محمدٍ النَّبِيِّ الأُمِّيِّ، وعلى آلِ محمدٍ، كما صَلَّيْتَ على آلِ إبراهيمَ، وبارِكْ على مُحمدٍ النبيِّ الأُمِّيِّ، وعلى آلِ مُحمدٍ، كما بارَكْتَ على آلِ إبراهيمَ في العالمينَ، إنَّك حميدٌ مجيدٌ.', 1, 'الورد السابع. (ص420)', '', '', 'اللهم صل على محمد النبي الأمي وعلى آل محمد كما صليت على آل إبراهيم وبارك على محمد النبي الأمي وعلى آل محمد كما باركت على آل إبراهيم في العالمين إنك حميد مجيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (710, 88, 1, '﴿ رَّبَّنَا عَلَيۡكَ تَوَكَّلۡنَا وَإِلَيۡكَ أَنَبۡنَا وَإِلَيۡكَ ٱلۡمَصِيرُ ٤ رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلَّذِينَ كَفَرُواْ وَٱغۡفِرۡ لَنَا رَبَّنَآۖ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴾', 1, 'الورد الثامن. [الممتحنة: ٤، ٥]. (ص421)', '', '', '﴿ ربنا عليۡك توكلۡنا وإليۡك أنبۡنا وإليۡك ٱلۡمصير ٤ ربنا لا تجۡعلۡنا فتۡنة للذين كفروا وٱغۡفرۡ لنا ربناۖ إنك أنت ٱلۡعزيز ٱلۡحكيم ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2048, 88, 2, 'ربنا أدخِلْنا ﴿ مَعَ ٱلۡقَوۡمِ ٱلصَّٰلِحِينَ ﴾', 1, 'الورد الثامن. [المائدة: ٨٤]. (ص421)', '', '', 'ربنا أدخلنا ﴿ مع ٱلۡقوۡم ٱلصلحين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (848, 88, 3, 'QuranText[(26:83:85)]', 1, 'الورد الثامن. [الشعراء: ٨٣ – ٨٥]. (ص421)', '', '', '268385', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (849, 88, 4, 'QuranText[(26:87:89)]', 1, 'الورد الثامن. [الشعراء: ٨٧ – ٨٩]. (ص421)', '', '', '268789', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2049, 88, 5, '﴿ حَسۡبِيَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ ﴾', 1, 'الورد الثامن. [التوبة: ١٢٩]. (ص421)', '', '', '﴿ حسۡبي ٱلله لا إله إلا هوۖ عليۡه توكلۡتۖ وهو رب ٱلۡعرۡش ٱلۡعظيم ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2050, 88, 6, '﴿ وَأُفَوِّضُ أَمۡرِيٓ إِلَى ٱللَّهِۚ إِنَّ ٱللَّهَ بَصِيرُۢ بِٱلۡعِبَادِ ﴾', 1, 'الورد الثامن. [غافر: ٤٤]. (ص422)', '', '', '﴿ وأفوض أمۡري إلى ٱللهۚ إن ٱلله بصيرۢ بٱلۡعباد ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2051, 88, 7, '﴿ وَمَا تَوۡفِيقِيٓ إِلَّا بِٱللَّهِۚ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ ﴾', 1, 'الورد الثامن. [هود: ٨٨]. (ص422)', '', '', '﴿ وما توۡفيقي إلا بٱللهۚ عليۡه توكلۡت وإليۡه أنيب ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2052, 88, 8, '﴿ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَعَلَيۡهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ ﴾', 1, 'الورد الثامن. [يوسف: ٦٧]. (ص422)', '', '', '﴿ إن ٱلۡحكۡم إلا للهۖ عليۡه توكلۡتۖ وعليۡه فلۡيتوكل ٱلۡمتوكلون ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2053, 88, 9, 'اللهُ اللهُ رَبِّي، لا أُشْرِكُ بِهِ شيئًا.', 1, 'الورد الثامن. (ص422)', '', '', 'الله الله ربي لا أشرك به شيئا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (631, 88, 10, 'لا إلهَ إلَّا اللهُ وحدَه، لا شريكَ له، اللهُ أكبرُ كبيرًا، والحمدُ لله كثيرًا، وسبحانَ اللهِ ربِّ العالمين، لا حولَ ولا قوَّةَ إلَّا باللهِ العزيزِ الحكيم، اللَّهُمَّ اغفِرْ لي، وارحمْني، واهدِني، وارزُقْني، وعافِني.', 1, 'الورد الثامن. (ص422)', '', '', 'لا إله إلا الله وحده لا شريك له الله أكبر كبيرا والحمد لله كثيرا وسبحان الله رب العالمين لا حول ولا قوة إلا بالله العزيز الحكيم اللهم اغفر لي وارحمني واهدني وارزقني وعافني', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2054, 88, 11, 'اللهُمَّ حَبِّبْ إِلَيَّ لقاءَكَ، وسَهِّلْ عَلَيَّ قضاءَكَ، وأَقْلِلْ لي من الدُّنيا.', 1, 'الورد الثامن. [الصحيحة: ١٣٣٨]. (ص422)', '', '', 'اللهم حبب إلي لقاءك وسهل علي قضاءك وأقلل لي من الدنيا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2055, 88, 12, 'رَضِينا باللهِ ربًّا، وبالإسلامِ دِينًا، وبمحمدٍ رَسُولًا، نعوذُ بالله مِنْ سُوءِ الفِتَن.', 1, 'الورد الثامن. (ص423)', '', '', 'رضينا بالله ربا وبالإسلام دينا وبمحمد رسولا نعوذ بالله من سوء الفتن', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (774, 88, 13, 'اللهم إنِّي أعوذُ بِكَ من العَجْزِ والكَسَلِ، والجُبْنِ والهَرَمِ، وأعوذُ بِكَ من عذابِ القَبْرِ، وأعوذُ بِكَ من فِتْنَةِ المحيا والممات.', 1, 'الورد الثامن. (ص423)', '', '', 'اللهم إني أعوذ بك من العجز والكسل والجبن والهرم وأعوذ بك من عذاب القبر وأعوذ بك من فتنة المحيا والممات', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (796, 88, 14, 'نعوذُ باللهِ من النارِ، نعوذُ باللهِ من الفتنِ؛ ما ظَهَرَ مِنْها، وما بَطَنَ، نعوذُ بالله من فِتنةِ الدَّجَّالِ.', 1, 'الورد الثامن. (ص423)', '', '', 'نعوذ بالله من النار نعوذ بالله من الفتن ما ظهر منها وما بطن نعوذ بالله من فتنة الدجال', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2056, 88, 15, 'اللهُمَّ إنَّا نعوذُ بِكَ أنْ نَرْجِعَ على أعقابِنا، أو نُفْتَنَ عن دِينِنا.', 1, 'الورد الثامن. [من دعاء عبد الله بن أبي مُلَيْكَة]. (ص423)', '', '', 'اللهم إنا نعوذ بك أن نرجع على أعقابنا أو نفتن عن ديننا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2057, 88, 16, 'اللهم إنِّي أعوذُ بِكَ من الحَوْرِ بعدَ الكَوْنِ.', 1, 'الورد الثامن. (ص423)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2058, 88, 17, 'أعوذُ بِعِزَّتِكَ أنْ تُضِلَّنِي، لا إلهَ إلَّا أنتَ الحَيُّ الذي لا يموتُ، والجِنُّ والإنسُ يموتون.', 1, 'الورد الثامن. (ص423)', '', '', 'أعوذ بعزتك أن تضلني لا إله إلا أنت الحي الذي لا يموت والجن والإنس يموتون', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2059, 88, 18, 'اللهُمَّ إنِّي أعوذُ بِوَجْهِكَ الكريم، وكلماتِكَ التَّامَّةِ مِنْ شَرِّ ما أنتَ آخِذٌ بناصِيَتِه، اللَّهُمَّ أنتَ تَكْشِفُ المَغْرَمَ والمأثَمَ، اللهُمَّ لا يُهْزَمُ جُنْدُكَ، ولا يُخْلَفُ وَعْدُكَ، ولا يَنْفَعُ ذا الجَدِّ مِنْكَ الجدُّ، سُبحانَكَ اللهُمَّ وبحمدِكَ.', 1, 'الورد الثامن. (ص424)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2060, 88, 19, 'أعوذُ بكلماتِ اللهِ التَّامَّاتِ التي لا يُجاوِزُهُنَّ بَرٌّ ولا فاجِرٌ، من شَرِّ ما خَلَقَ وَذَرَأَ وبَرَأَ، ومن شَرِّ ما ينزلُ من السماءِ، ومن شرِّ ما يَعْرُجُ فيها، ومن شرِّ ما ذرأَ في الأرضِ وبرَأَ، ومن شرِّ ما يخرجُ منها، ومن شَرِّ فتنِ الليلِ والنهارِ، ومن شَرِّ كُلِّ طارقٍ يطرُقُ، إلَّا طارقًا يطرُقُ بخيرٍ يا رحمنُ.', 1, 'الورد الثامن. (ص424)', '', '', 'أعوذ بكلمات الله التامات التي لا يجاوزهن بر ولا فاجر من شر ما خلق وذرأ وبرأ ومن شر ما ينزل من السماء ومن شر ما يعرج فيها ومن شر ما ذرأ في الأرض وبرأ ومن شر ما يخرج منها ومن شر فتن الليل والنهار ومن شر كل طارق يطرق إلا طارقا يطرق بخير يا رحمن', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2061, 88, 20, 'اللهُمَّ أَلِّفْ بين قلوبِنا، وأصلِحْ ذاتَ بينِنا، واهْدِنا سُبُلَ السَّلامِ، ونَجِّنا مِنَ الظُّلُماتِ إلى النُّورِ، وجَنِّبْنا الفواحِشَ؛ ما ظَهَرَ مِنْها، وما بطنَ، وبارِكْ لنا في أسماعِنا، وأبصارِنا، وقلوبِنا، وأزواجِنا، وذُرِّيَّاتِنا، وتُبْ عَلَيْنَا، إنَّكَ أنتَ التوَّابُ الرَّحيمُ، واجعلْنا شاكرِينَ لنعمتِكَ، مُثْنِينَ بها عَلَيْكَ، قابِلينَ لها، وأَتْمِمْها علينا.', 1, 'الورد الثامن. (ص424–425)', '', '', 'اللهم ألف بين قلوبنا وأصلح ذات بيننا واهدنا سبل السلام ونجنا من الظلمات إلى النور وجنبنا الفواحش ما ظهر منها وما بطن وبارك لنا في أسماعنا وأبصارنا وقلوبنا وأزواجنا وذرياتنا وتب علينا إنك أنت التواب الرحيم واجعلنا شاكرين لنعمتك مثنين بها عليك قابلين لها وأتممها علينا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2062, 88, 21, 'اللهُمَّ إنِّي أعوذُ بِكَ من جارِ السُّوءِ، ومن زوجٍ تُشَيِّبُني قبلَ المشيب، ومن ولَدٍ يكونُ عليَّ رَبًّا، ومن مالٍ يكونُ عَلَيَّ عذابًا، ومن خليلٍ ماكرٍ عينُه تراني، وقلبُه يَرْعاني؛ إن رأى حَسَنَةً دفَنَها، وإذا رأى سيئةً أذاعَها.', 1, 'الورد الثامن. (ص425)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (717, 88, 22, 'اللهُمَّ صَلِّ على محمدٍ عبدِكَ ورسولِكَ، كما صَلَّيْتَ على آلِ إبراهيمَ، وبارِكْ على محمدٍ عبدِكَ ورسولِكَ، وعلى آلِ مُحَمَّدٍ، كما بارَكْتَ على إبراهيمَ، وعلى آلِ إبراهيم.', 1, 'الورد الثامن. (ص425)', '', '', 'اللهم صل على محمد عبدك ورسولك كما صليت على آل إبراهيم وبارك على محمد عبدك ورسولك وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2063, 89, 1, 'QuranText[(37:180:182)]', 1, 'الورد التاسع. [الصافات: ١٨٠-١٨٢]. (ص426)', '', '', '37180182', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2064, 89, 2, 'اللَّهُمَّ اجعل ﴿ لَّنَا مِن لَّدُنكَ وَلِيّٗا وَٱجۡعَل لَّنَا مِن لَّدُنكَ نَصِيرًا ﴾', 1, 'الورد التاسع. [النساء: ٧٥]. (ص426)', '', '', 'اللهم اجعل ﴿ لنا من لدنك وليا وٱجۡعل لنا من لدنك نصيرا ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2065, 89, 3, 'لا إله إلا الله وحده، لا شريك له، له الملك، وله الحمدُ، وهُوَ على كل شيءٍ قديرٌ، لا حول ولا قوة إلا بالله، لا إله إلا الله، ولا نعبدُ إلا إيَّاه، له النِّعمةُ، وله الفضلُ، وله الثناءُ الحَسَنُ، لا إله إلا الله، مُخلِصِين له الدينَ، ولو كَرِهَ الكافرون.', 1, 'الورد التاسع. (ص426)', '', '', 'لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير لا حول ولا قوة إلا بالله لا إله إلا الله ولا نعبد إلا إياه له النعمة وله الفضل وله الثناء الحسن لا إله إلا الله مخلصين له الدين ولو كره الكافرون', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2066, 89, 4, 'اللَّهُمَّ رَبَّ السماواتِ وربَّ الأرضِ وربَّ العرشِ العظيمِ، ربَّنا وربَّ كُلِّ شيءٍ، فالِقَ الحَبِّ والنَّوى، مُنْزِلَ التوراةِ والإنجيلِ والفُرْقانِ، أعوذ بك من شرِّ كُلِّ ذي شرٍّ أنت آخِذٌ بناصيته، أنت الأوَّلُ فليس قَبْلَكَ شيءٌ، وأنت الآخِرُ فليس بعدَكَ شيء، وأنت الظاهرُ فليس فوقَكَ شيء، وأنت الباطنُ فليس دُونَكَ شيء، اقْضِ عَنَّا الدَّيْنَ، وأَغْنِنا من الفقر.', 1, 'الورد التاسع. (ص426–427)', '', '', 'اللهم رب السماوات ورب الأرض ورب العرش العظيم ربنا ورب كل شيء فالق الحب والنوى منزل التوراة والإنجيل والفرقان أعوذ بك من شر كل ذي شر أنت آخذ بناصيته أنت الأول فليس قبلك شيء وأنت الآخر فليس بعدك شيء وأنت الظاهر فليس فوقك شيء وأنت الباطن فليس دونك شيء اقض عنا الدين وأغننا من الفقر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (648, 89, 5, '﴿ رَّبِّ زِدۡنِي عِلۡمٗا ﴾', 1, 'الورد التاسع. [طه: ١١٤]. (ص427)', '', '', '﴿ رب زدۡني علۡما ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2067, 89, 6, 'اللهم فَقِّهْني في الدِّين، وعَلِّمْني التأويل.', 1, 'الورد التاسع. (ص427)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (656, 89, 7, 'اللهم إني أسألك علمًا نافعًا، وأعوذ بك من علمٍ لا ينفع.', 1, 'الورد التاسع. (ص427)', '', '', 'اللهم إني أسألك علما نافعا وأعوذ بك من علم لا ينفع', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2068, 89, 8, 'اللهم انفعني بما عَلَّمْتَنِي، وعَلِّمْنِي ما ينفعُنِي، وَزِدْنِي عِلْمًا.', 1, 'الورد التاسع. (ص427)', '', '', 'اللهم انفعني بما علمتني وعلمني ما ينفعني وزدني علما', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (858, 89, 9, 'اللهم اهدِني وَسَدِّدْني.', 1, 'الورد التاسع. (ص427)', '', '', 'اللهم اهدني وسددني', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2069, 89, 10, 'الحمدُ لله الذي كَفاني وآواني، وأطعَمَني وأسْقَاني، والذي مَنَّ عَلَيَّ فأَفضَلَ، والذي أعطاني فأَجْزَلَ، الحمدُ للهِ على كُلِّ حالٍ، اللهم ربَّ كُلِّ شيءٍ ومَلِيكَه، وإلهَ كُلِّ شيءٍ، أعوذُ بك من النار.', 1, 'الورد التاسع. (ص428)', '', '', 'الحمد لله الذي كفاني وآواني وأطعمني وأسقاني والذي من علي فأفضل والذي أعطاني فأجزل الحمد لله على كل حال اللهم رب كل شيء ومليكه وإله كل شيء أعوذ بك من النار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2070, 89, 11, 'اللهم إنا نستعينُك ونستغفِرُك، ولا نَكْفُرُكَ، ونؤمن بك، ونَخْلَعُ مَنْ يَفْجُرُكَ، اللهم إياك نعبد، ولك نصلي ونسجد، وإليك نسعى ونَحْفِدُ، نرجو رحمتك ونخشى عذابَك، إنَّ عذابَكَ الجِدَّ بالكُفارِ مُلْحِق.
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2071, 89, 12, 'اللهم اجعلْ علينا صلاةَ قومٍ أبرارٍ، يقومون الليلَ، ويصومونَ النهارَ، ليسوا بِأَثَمَةٍ ولا فُجَّارٍ.', 1, 'الورد التاسع. (ص429)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2072, 89, 13, 'ربَّنا آتنا في الدنيا حسنةً، وفي الآخِرَةِ حسنةً، وَقِنَا عذابَ النار.', 1, 'الورد التاسع. (ص429)', '', '', 'ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (772, 89, 14, 'اللهم اغفر لي ذنوبي وخطاياي كُلَّها، اللهم أَنْعِشْني، واجْبُرْني، واهدني لصالحِ الأعمالِ والأخلاق، فإنه لا يَهْدِي لصالحِها، ولا يَصْرِفُ سَيِّئَها إلا أنت.', 1, 'الورد التاسع. (ص430)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (797, 89, 15, 'اللهم إني أعوذ بك من فتنةِ النار، وعذابِ النار، ومن شرِّ الغِنى والفقر.', 1, 'الورد التاسع. (ص430)', '', '', 'اللهم إني أعوذ بك من فتنة النار وعذاب النار ومن شر الغنى والفقر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (729, 89, 16, 'اللهم اسْتُرْ عَوْرَتي، وآمِن رَوْعَتِي، واقْضِ عَنِّي دَيْني.', 1, 'الورد التاسع. (ص430)', '', '', 'اللهم استر عورتي وآمن روعتي واقض عني ديني', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (794, 89, 17, 'اللهم رحمتَك أرجو، فلا تَكِلْني إلى نفسي طَرْفَةَ عينٍ، وأَصْلِحْ لي شأني كلَّه، لا إله إلا أنت.', 1, 'الورد التاسع. (ص430)', '', '', 'اللهم رحمتك أرجو فلا تكلني إلى نفسي طرفة عين وأصلح لي شأني كله لا إله إلا أنت', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2073, 89, 18, 'اللهم إنا نعوذ بك من شرور أنفسِنا وسيئاتِ أعمالنا.', 1, 'الورد التاسع. (ص430)', '', '', 'اللهم إنا نعوذ بك من شرور أنفسنا وسيئات أعمالنا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2074, 89, 19, 'اللهُمَّ إني أسألُكَ إيمانًا لا يرتدُّ، ونعيمًا لا ينفدُ، ومُرافقةَ نبيِّكَ محمدٍ ﷺ في أعلى جَنَّةِ الخُلْد.', 1, 'الورد التاسع. [من دُعاءِ عبدِ اللهِ بنِ مَسْعودٍ رضي الله عنه]. (ص431)', '', '', 'اللهم إني أسألك إيمانا لا يرتد ونعيما لا ينفد ومرافقة نبيك محمد في أعلى جنة الخلد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (860, 89, 20, 'اللهُمَّ صَلِّ على محمدٍ وعلى آلِ محمدٍ، كما صلَّيتَ على إبراهيمَ، وعلى آلِ إبراهيمَ، إنَّك حميدٌ مجيدٌ، اللهُمَّ بارِكْ على محمدٍ وعلى آلِ محمدٍ، كما باركتَ على إبراهيمَ وعلى آلِ إبراهيمَ، إنَّك حميدٌ مجيد.', 1, 'الورد التاسع. (ص431)', '', '', 'اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2075, 90, 1, '﴿ أَعُوذُ بِٱللَّهِ أَنۡ أَكُونَ مِنَ ٱلۡجَٰهِلِينَ ﴾', 1, 'الورد العاشر. [البقرة: ٦٧]. (ص432)', '', '', '﴿ أعوذ بٱلله أنۡ أكون من ٱلۡجهلين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (630, 90, 2, '﴿ رَّبِّ أَدۡخِلۡنِي مُدۡخَلَ صِدۡقٖ وَأَخۡرِجۡنِي مُخۡرَجَ صِدۡقٖ وَٱجۡعَل لِّي مِن لَّدُنكَ سُلۡطَٰنٗا نَّصِيرٗا ﴾', 1, 'الورد العاشر. [الإسراء: ٨٠]. (ص432–433)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2076, 90, 3, '﴿ عَسَىٰٓ أَن يَهۡدِيَنِ رَبِّي لِأَقۡرَبَ مِنۡ هَٰذَا رَشَدٗا ﴾', 1, 'الورد العاشر. [الكهف: ٢٤]. (ص434)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2077, 90, 4, '﴿ لَئِن لَّمۡ يَهۡدِنِي رَبِّي لَأَكُونَنَّ مِنَ ٱلۡقَوۡمِ ٱلضَّآلِّينَ ﴾', 1, 'الورد العاشر. [الأنعام: ٧٧]. (ص434)', '', '', '﴿ لئن لمۡ يهۡدني ربي لأكونن من ٱلۡقوۡم ٱلضالين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (711, 90, 5, '﴿ رَبَّنَآ أَتۡمِمۡ لَنَا نُورَنَا وَٱغۡفِرۡ لَنَآۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴾', 1, 'الورد العاشر. [التحريم: ٨]. (ص434)', '', '', '﴿ ربنا أتۡممۡ لنا نورنا وٱغۡفرۡ لناۖ إنك على كل شيۡء قدير ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2078, 90, 6, 'اللهم اجعل في قلبي نورًا، وفي لساني نورًا، واجعل في سمعي نورًا، واجعل في بصري نورًا، واجعلْ مِن تحتي نورًا، واجعل من فوقي نورًا، وعن يميني نورًا، وعن يساري نورًا، واجعل أمامي نورًا، واجعل خَلْفي نورًا، واجعل في نفسي نورًا، وأعْظِمْ لي نورًا.', 1, 'الورد العاشر. (ص434)', '', '', 'اللهم اجعل في قلبي نورا وفي لساني نورا واجعل في سمعي نورا واجعل في بصري نورا واجعل من تحتي نورا واجعل من فوقي نورا وعن يميني نورا وعن يساري نورا واجعل أمامي نورا واجعل خلفي نورا واجعل في نفسي نورا وأعظم لي نورا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2079, 90, 7, 'الحمد لله حمدًا كثيرًا طيبًا مباركًا فيه.', 1, 'الورد العاشر. (ص435)', '', '', 'الحمد لله حمدا كثيرا طيبا مباركا فيه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (605, 90, 8, 'لا إله إلا اللهُ العظيمُ الحليم، لا إله إلا اللهُ ربُّ العرشِ العظيم، لا إله إلا اللهُ ربُّ السماواتِ والأرض، لا إله إلا اللهُ ربُّ العرشِ الكريم.', 1, 'الورد العاشر. (ص435)', '', '', 'لا إله إلا الله العظيم الحليم لا إله إلا الله رب العرش العظيم لا إله إلا الله رب السماوات والأرض لا إله إلا الله رب العرش الكريم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2080, 90, 9, 'ربنا لك الحمدُ، مِلْءَ السماوات، ومِلْءَ الأرضِ، ومِلْءَ ما بينهما، ومِلْءَ مَا شِئْتَ من شيءٍ بَعْدُ، أَهْلَ الثناءِ والمجدِ، أَحَقُّ ما قال العبدُ، وكُلُّنا لك عبد، اللهم لا مانعَ لما أعطيتَ، ولا مُعْطِيَ لما منعتَ، ولا ينفعُ ذا الجَدِّ مِنكَ الجَدُّ.', 1, 'الورد العاشر. (ص435)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (650, 90, 10, 'اللهم إني أسألك بأن لك الحمدَ، لا إله إلا أنت وحدك لا شريك لك، المنانُ، يا بديعَ السماواتِ والأرض، يا ذا الجلالِ والإكرام، يا حيُّ يا قيُّومُ، إني أسألك الجنةَ، وأعوذُ بك من النار.', 1, 'الورد العاشر. (ص435)', '', '', 'اللهم إني أسألك بأن لك الحمد لا إله إلا أنت وحدك لا شريك لك المنان يا بديع السماوات والأرض يا ذا الجلال والإكرام يا حي يا قيوم إني أسألك الجنة وأعوذ بك من النار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2081, 90, 11, 'سبحانك اللهم ربَّنا وبحمدك، اللهم اغفر لي.', 1, 'الورد العاشر. (ص436)', '', '', 'سبحانك اللهم ربنا وبحمدك اللهم اغفر لي', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2082, 90, 12, 'اللهم اغسل خطاياي بماءِ الثَّلجِ والبَرَدِ، ونَقِّ قلبي من الخطايا كما نقَّيْتَ الثوبَ الأبيضَ مِنَ الدَّنَسِ.', 1, 'الورد العاشر. (ص436)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2083, 90, 13, 'اللهم اهدني فيمن هديت، وعافني فيمن عافيت، وتولَّني فيمن توليت، وبارك لي فيما أعطيتَ، وقِني شرَّ ما قضيت، فإنك تقضي ولا يُقضى عليك، وإنه لا يَذِلُّ مَنْ وَالَيْتَ، ولا يَعِزُّ من عاديت، تباركْتَ رَبَّنا وتعاليتَ، لا مَنْجا منك إلا إليك.', 1, 'الورد العاشر. (ص436)', '', '', 'اللهم اهدني فيمن هديت وعافني فيمن عافيت وتولني فيمن توليت وبارك لي فيما أعطيت وقني شر ما قضيت فإنك تقضي ولا يقضى عليك وإنه لا يذل من واليت ولا يعز من عاديت تباركت ربنا وتعاليت لا منجا منك إلا إليك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (658, 90, 14, 'اللهم إني أسألك الفِرْدَوْسَ الأعلى من الجنة.', 1, 'الورد العاشر. (ص436)', '', '', 'اللهم إني أسألك الفردوس الأعلى من الجنة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2084, 90, 15, 'اللهم أَعِذْني من عذابٍ في النار، وعذابٍ في القبر.', 1, 'الورد العاشر. (ص436)', '', '', 'اللهم أعذني من عذاب في النار وعذاب في القبر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2085, 90, 16, 'اللهم إني أسألك العافيةَ واليقين.', 1, 'الورد العاشر. (ص436)', '', '', 'اللهم إني أسألك العافية واليقين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (859, 90, 17, 'يا مُقَلِّبَ القلوبِ ثَبِّتْ قلبي على دِينك.', 1, 'الورد العاشر. (ص436)', '', '', 'يا مقلب القلوب ثبت قلبي على دينك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2086, 90, 18, 'يا وليَّ الإسلامِ وأهلِه، ثَبِّتْني به حتى ألقاك.', 1, 'الورد العاشر. (ص437)', '', '', 'يا ولي الإسلام وأهله ثبتني به حتى ألقاك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (804, 90, 19, 'اللهم مَتِّعْني باسمعي وبصري، واجعلْهُما الوارِثَ مِنِّي، وانْصُرْني على مَن ظلمني، وخُذْ منه بثأري.', 1, 'الورد العاشر. (ص437)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (731, 90, 20, 'اللهم إني أعوذ بك من شرِّ جارِ السُّوءِ في دارِ المُقام.', 1, 'الورد العاشر. (ص437)', '', '', 'اللهم إني أعوذ بك من شر جار السوء في دار المقام', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2087, 90, 21, 'اللهم لا سَهْلَ إلا ما جعلتَهُ سهلًا، وأنت تجعلُ الحَزْنَ إذا شئتَ سَهْلًا.', 1, 'الورد العاشر. [الصحيحة: ٢٨٨٦]. (ص437)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2088, 90, 22, 'أعوذ بالله أن أكون في نفسي عظيمًا، وعند الله صغيرًا.', 1, 'الورد العاشر. [من قول عتبة بن غزوان رضي الله عنه]. (ص437)', '', '', 'أعوذ بالله أن أكون في نفسي عظيما وعند الله صغيرا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2089, 90, 23, 'اللهم ارزقني حُبَّك، وحُبَّ مَن ينفعُني حُبُّه عِندك، اللهم ما رَزَقتني مما أُحِبُّ؛ فاجعلْه قُوةً لي فيما تُحِب، اللهم وما زَوَيْتَ عني مما أُحِبُّ، فاجعلْه فَراغًا لي فيما تُحِبُّ.', 1, 'الورد العاشر. [موقوف عن عبد الله بن يزيد الخطمي الأنصاري رضي الله عنه]. (ص437)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2090, 90, 24, 'تَمَّ نورُكَ فهديتَ فلك الحمد، وعَظُمَ حِلْمُكَ فعفوتَ فلك الحمد، و بسطتَ يدَكَ فأعطيتَ فلك الحمد، ربَّنا وجهُكَ أكرمُ الوجوهِ، وجاهُكَ خيرُ الجاهِ، وعَطِيَّتُكَ أفضلُ العَطِيَّة، وأهنؤها، تُطاعُ رَبَّنَا فَتَشْكُرُ، وتُعصَى ربنا فتغفِر، تُجيبُ المضْطَرَّ، وتكشِفُ الضُّرَّ، وتَشْفي السقيمَ، وتُنَجِّي مِنَ الكَرْبِ، وتقبلُ التوبةَ، وتغفر الذنبَ لمن شِئتَ، لا يَجْزِي بآلائك أحدٌ، ولا يُحصِي نَعْماءَكَ قولُ قائل.', 1, 'الورد العاشر. [موقوف عن أمير المؤمنين علي رضي الله عنه]. (ص438)', '', '', 'تم نورك فهديت فلك الحمد وعظم حلمك فعفوت فلك الحمد و بسطت يدك فأعطيت فلك الحمد ربنا وجهك أكرم الوجوه وجاهك خير الجاه وعطيتك أفضل العطية وأهنؤها تطاع ربنا فتشكر وتعصى ربنا فتغفر تجيب المضطر وتكشف الضر وتشفي السقيم وتنجي من الكرب وتقبل التوبة وتغفر الذنب لمن شئت لا يجزي بآلائك أحد ولا يحصي نعماءك قول قائل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (636, 90, 25, 'اللهم صَلِّ على محمدٍ النَّبيِّ الأُمِّيِّ، وعلى آلِ محمد، كما صليتَ على آل إبراهيمَ، وبارِك على محمدٍ النبيِّ الأُمِّيِّ وعلى آلِ محمد، كما باركتَ على آل إبراهيمَ في العالمين، إنك حميد مجيد.', 1, 'الورد العاشر. (ص438)', '', '', 'اللهم صل على محمد النبي الأمي وعلى آل محمد كما صليت على آل إبراهيم وبارك على محمد النبي الأمي وعلى آل محمد كما باركت على آل إبراهيم في العالمين إنك حميد مجيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (828, 91, 1, '﴿ رَبَّنَا تَقَبَّلۡ مِنَّآۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴾', 1, 'الورد الحادي عشر. [البقرة: ١٢٧]. (ص439)', '', '', '﴿ ربنا تقبلۡ مناۖ إنك أنت ٱلسميع ٱلۡعليم ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2091, 91, 2, '﴿ وَتُبۡ عَلَيۡنَآۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ ﴾', 1, 'الورد الحادي عشر. [البقرة: ١٢٨]. (ص439)', '', '', '﴿ وتبۡ عليۡناۖ إنك أنت ٱلتواب ٱلرحيم ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (829, 91, 3, '﴿ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ ﴾', 1, 'الورد الحادي عشر. [البقرة: ٢٠١]. (ص439)', '', '', '﴿ ربنا ءاتنا في ٱلدنۡيا حسنة وفي ٱلۡأخرة حسنة وقنا عذاب ٱلنار ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2092, 91, 4, '﴿ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ عَٰلِمَ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ أَنتَ تَحۡكُمُ بَيۡنَ عِبَادِكَ فِي مَا كَانُواْ فِيهِ يَخۡتَلِفُونَ ﴾ [الزمر: ٤٦]، اهدِني لما اختُلِفَ فيه من الحقِّ بإذنِكَ، إنَّك تهدي مَنْ تشاءُ إلى صراطٍ مستقيم.', 1, 'الورد الحادي عشر. (ص439)', '', '', '﴿ ٱللهم فاطر ٱلسموت وٱلۡأرۡض علم ٱلۡغيۡب وٱلشهدة أنت تحۡكم بيۡن عبادك في ما كانوا فيه يخۡتلفون ﴾ الزمر ٤٦ اهدني لما اختلف فيه من الحق بإذنك إنك تهدي من تشاء إلى صراط مستقيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (689, 91, 5, '﴿ رَّبِّ ٱغۡفِرۡ وَٱرۡحَمۡ وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ ﴾', 1, 'الورد الحادي عشر. [المؤمنون: ١١٨]. (ص439)', '', '', '﴿ رب ٱغۡفرۡ وٱرۡحمۡ وأنت خيۡر ٱلرحمين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (607, 91, 6, '﴿ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِيٓ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴾', 1, 'الورد الحادي عشر. [آل عمران: ١٤٧]. (ص440)', '', '', '﴿ ربنا ٱغۡفرۡ لنا ذنوبنا وإسۡرافنا في أمۡرنا وثبتۡ أقۡدامنا وٱنصرۡنا على ٱلۡقوۡم ٱلۡكفرين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (748, 91, 7, '﴿ رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلۡإِيمَٰنِ وَلَا تَجۡعَلۡ فِي قُلُوبِنَا غِلّٗا لِّلَّذِينَ ءَامَنُواْ رَبَّنَآ إِنَّكَ رَءُوفٞ رَّحِيمٌ ﴾', 1, 'الورد الحادي عشر. [الحشر: ١٠]. (ص440)', '', '', '﴿ ربنا ٱغۡفرۡ لنا ولإخۡوننا ٱلذين سبقونا بٱلۡإيمن ولا تجۡعلۡ في قلوبنا غلا للذين ءامنوا ربنا إنك رءوف رحيم ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (627, 91, 8, '﴿ عَلَى ٱللَّهِ تَوَكَّلۡنَا رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ ٨٥ وَنَجِّنَا بِرَحۡمَتِكَ مِنَ ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ﴾', 1, 'الورد الحادي عشر. [يونس: ٨٥، ٨٦]. (ص440)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (608, 91, 9, '﴿ رَبَّنَا لَا تَجۡعَلۡنَا مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ ﴾', 1, 'الورد الحادي عشر. [الأعراف: ٤٧]. (ص440)', '', '', '﴿ ربنا لا تجۡعلۡنا مع ٱلۡقوۡم ٱلظلمين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2093, 91, 10, '﴿ رَبِّ نَجِّنِي مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ ﴾', 1, 'الورد الحادي عشر. [القصص: ٢١]. (ص440)', '', '', '﴿ رب نجني من ٱلۡقوۡم ٱلظلمين ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2094, 91, 11, 'لا إله إلا اللهُ وحدَه، أعزَّ جُنْدَه، ونصرَ عبدَه، وغَلَبَ الأحزابَ وحدَه، فلا شيءَ بعدَه.', 1, 'الورد الحادي عشر. (ص440)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2095, 91, 12, 'اللهُ اللهُ رَبِّي، لا شريكَ له.', 1, 'الورد الحادي عشر. (ص441)', '', '', 'الله الله ربي لا شريك له', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2096, 91, 13, 'يا حيُّ يا قيُّومُ، برحمتِكَ أستغيثُ.', 1, 'الورد الحادي عشر. (ص441)', '', '', 'يا حي يا قيوم برحمتك أستغيث', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2097, 91, 14, 'اللهُمَّ إنِّي أسألُكَ بأنِّي أشهدُ أنَّك أنتَ الله الذي لا إله إلا أنتَ، الأحدُ الصمدُ، الذي لم يَلِد، ولم يُولد، ولم يكن له كُفُوًا أحدٌ، أن تغفِرَ لي ذُنُوبي، إنَّك أنتَ الغفور الرحيم.', 1, 'الورد الحادي عشر. (ص441)', '', '', 'اللهم إني أسألك بأني أشهد أنك أنت الله الذي لا إله إلا أنت الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفوا أحد أن تغفر لي ذنوبي إنك أنت الغفور الرحيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2098, 91, 15, 'اللهم لك الحمدُ، مِلْءَ السماواتِ، ومِلْءَ الأرضِ، ومِلْءَ ما شِئتَ مِن شيءٍ بعدُ، اللهم طَهِّرْني بالثلج والبَرَد والماء البارد، اللهم طَهِّرني من الذنوب والخطايا كما يُنَقَّى الثوبُ الأبيضُ من الدَّنَس.', 1, 'الورد الحادي عشر. (ص441)', '', '', 'اللهم لك الحمد ملء السماوات وملء الأرض وملء ما شئت من شيء بعد اللهم طهرني بالثلج والبرد والماء البارد اللهم طهرني من الذنوب والخطايا كما ينقى الثوب الأبيض من الدنس', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (776, 91, 16, 'اللهمَّ إني أعوذُ بِكَ من غَلَبَةِ الدَّيْنِ، وغلبةِ العَدُوِّ، وشماتةِ الأعداء.', 1, 'الورد الحادي عشر. (ص441)', '', '', 'اللهم إني أعوذ بك من غلبة الدين وغلبة العدو وشماتة الأعداء', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (795, 91, 17, 'اللهم إني أعوذُ بِكَ من مُنكراتِ الأخلاقِ والأعمالِ والأهواء.', 1, 'الورد الحادي عشر. (ص441)', '', '', 'اللهم إني أعوذ بك من منكرات الأخلاق والأعمال والأهواء', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (696, 91, 18, 'اللهم إنا نسألُكَ أن تستُرَ عوراتِنا، وتُؤَمِّنَ رَوْعاتِنا.', 1, 'الورد الحادي عشر. (ص442)', '', '', 'اللهم إنا نسألك أن تستر عوراتنا وتؤمن روعاتنا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (655, 91, 19, 'اللهمَّ إنِّي أعوذُ بِكَ من جَهْدِ البلاءِ، ودَرَكِ الشقاءِ، وسُوءِ القضاءِ، وشماتةِ الأعداء.', 1, 'الورد الحادي عشر. (ص442)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2099, 91, 20, 'اللهم اغفِر لي ذنبي، ووَسِّعْ لي في داري، وبارِكْ لي في رِزقي.', 1, 'الورد الحادي عشر. (ص442)', '', '', 'اللهم اغفر لي ذنبي ووسع لي في داري وبارك لي في رزقي', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (775, 91, 21, 'اللهم إني أعوذُ بِكَ من القسوةِ، والغفلةِ، والعَيْلَةِ، والذِّلَّةِ، والمَسْكَنَةِ، وأعوذُ بِكَ من الفقرِ، والكفرِ، والفسوقِ، والشقاقِ، والسُّمعةِ والرياءِ، وأعوذُ بِكَ من الصَّمَمِ والبَكَمِ، والجنونِ والجُذامِ، وسَيِّئِ الأسقام.', 1, 'الورد الحادي عشر. (ص442)', '', '', 'اللهم إني أعوذ بك من القسوة والغفلة والعيلة والذلة والمسكنة وأعوذ بك من الفقر والكفر والفسوق والشقاق والسمعة والرياء وأعوذ بك من الصمم والبكم والجنون والجذام وسيئ الأسقام', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (730, 91, 22, 'اللهم إني أعوذُ بِكَ من البَرَصِ والجنونِ والجُذَامِ، ومن سَيِّئِ الأسقام.', 1, 'الورد الحادي عشر. (ص442)', '', '', 'اللهم إني أعوذ بك من البرص والجنون والجذام ومن سيئ الأسقام', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (801, 91, 23, 'اللهم إني أعوذُ بِك من الهَدْمِ، وأعوذ بك من التردِّي، وأعوذُ بِكَ من الغَرَقِ، والحَرَقِ، والهَرَمِ، وأعوذُ بِكَ أن يَتَخَبَّطَنِيَ الشيطانُ عند الموتِ، وأعوذُ بِكَ أن أموتَ في سبيلِكَ مُدبِرًا، وأعوذُ بِكَ أنْ أموتَ لَدِيغًا.', 1, 'الورد الحادي عشر. (ص442)', '', '', 'اللهم إني أعوذ بك من الهدم وأعوذ بك من التردي وأعوذ بك من الغرق والحرق والهرم وأعوذ بك أن يتخبطني الشيطان عند الموت وأعوذ بك أن أموت في سبيلك مدبرا وأعوذ بك أن أموت لديغا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2100, 91, 24, 'اللهم اغفِرْ لنا وارحمنا، وبارِكْ علينا، ووَسِّعْ علينا في أرزاقِنا.', 1, 'الورد الحادي عشر. [المسند: ١٧٦٧٨]. (ص443)', '', '', 'اللهم اغفر لنا وارحمنا وبارك علينا ووسع علينا في أرزاقنا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2101, 91, 25, 'اللهم انفعني بما عَلَّمْتَني، وعَلِّمْني ما ينفعُني، وارزقني علمًا تنفعُني به.', 1, 'الورد الحادي عشر. [الصحيحة: ٣١٥١]. (ص443)', '', '', 'اللهم انفعني بما علمتني وعلمني ما ينفعني وارزقني علما تنفعني به', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (798, 91, 26, 'اللهم رَبَّ جبرائيلَ وميكائيلَ، وربَّ إسرافيلَ، أعوذُ بك من حَرِّ النار، وعذابِ القبر.', 1, 'الورد الحادي عشر. (ص443)', '', '', 'اللهم رب جبرائيل وميكائيل ورب إسرافيل أعوذ بك من حر النار وعذاب القبر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2102, 91, 27, 'اللهم إني أسألُكَ تَمامَ النِّعمة.', 1, 'الورد الحادي عشر. (ص443)', '', '', 'اللهم إني أسألك تمام النعمة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (850, 91, 28, 'اللهم إني أسألك الجنة.', 3, 'الورد الحادي عشر. (ص443)', '', '', 'اللهم إني أسألك الجنة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (851, 91, 29, 'اللهم إنِّي أعوذُ بكَ من النار.', 3, 'الورد الحادي عشر. (ص443)', '', '', 'اللهم إني أعوذ بك من النار', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2103, 91, 30, 'اللهُمَّ مُنَّ عَلَيْنَا، وَقِنَا عذابَ السَّموم، إنَّك أنتَ البَرُّ الرَّحيم.', 1, 'الورد الحادي عشر. [موقوفٌ على أُمِّ المؤمنين عائشةَ رضي الله عنها]. (ص443)', '', '', 'اللهم من علينا وقنا عذاب السموم إنك أنت البر الرحيم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (777, 91, 31, 'اللهم صَلِّ على محمدٍ عبدِكَ ورسولِكَ النبيِّ الأُمِّيِّ، وعلى آلِ محمدٍ وأزواجِهِ وذُرِّيَّتِه، كما صَلَّيْتَ على إبراهيمَ وعلى آلِ إبراهيم، وبارِكْ على محمدٍ النبيِّ الأُمِّي، وعلى آلِ محمدٍ وأزواجِهِ وذُرِّيَّتِهِ، كما باركتَ على إبراهيمَ، وعلى آلِ إبراهيمَ في العالمين، إنَّكَ حميدٌ مجيد.', 1, 'الورد الحادي عشر. (ص443–444)', '', '', 'اللهم صل على محمد عبدك ورسولك النبي الأمي وعلى آل محمد وأزواجه وذريته كما صليت على إبراهيم وعلى آل إبراهيم وبارك على محمد النبي الأمي وعلى آل محمد وأزواجه وذريته كما باركت على إبراهيم وعلى آل إبراهيم في العالمين إنك حميد مجيد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2104, 91, 32, 'سبحان الله وبحمدِه، سبحانك اللهم وبحمدك، أشهدُ أن لا إله إلا أنتَ، أستغفِرُك، وأتوبُ إليك.', 1, 'الورد الحادي عشر. (ص444)', '', '', 'سبحان الله وبحمده سبحانك اللهم وبحمدك أشهد أن لا إله إلا أنت أستغفرك وأتوب إليك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (2105, 91, 33, 'تمَّ الكِتابُ، والحمدُ لله رَبِّ العالمين أولًا وآخِرًا، وظاهِرًا وباطِنًا، وصَلَّى اللهُ وسَلَّمَ وبَارَكَ عَلَى عبدِهِ ورسُولِهِ وخَليلِهِ محمدٍ خيرِ خلقِهِ أجمعين، كُلَّمَا ذَكَرَهُ الذَّاكرونَ، وغَفَلَ عن ذِكْرِهِ الغافلون، وعلى آلِهِ وأصحابِهِ وأتباعِهِم بإحسانٍ إلى يومِ الدِّين.', 0, 'الورد الحادي عشر. (ص444)', '', '', 'تم الكتاب والحمد لله رب العالمين أولا وآخرا وظاهرا وباطنا وصلى الله وسلم وبارك على عبده ورسوله وخليله محمد خير خلقه أجمعين كلما ذكره الذاكرون وغفل عن ذكره الغافلون وعلى آله وأصحابه وأتباعهم بإحسان إلى يوم الدين', '', '');
